import { type Address, type Log, parseEventLogs } from "viem";
import { primaryOfferingAbi } from "@/lib/offering/config";

/**
 * Pure decode/validate half of the settlement trust boundary (the I/O half — fetching the
 * receipt and reading the offering — lives in `verify.ts`, which is server-only). Kept separate so
 * this logic is unit-testable without mocking an RPC client.
 */

/** Thrown when the on-chain logs don't yield exactly one matching Subscribed event. */
export class SettlementDecodeError extends Error {}

export interface SubscribedArgs {
  offeringId: bigint;
  investor: Address;
  quantity: bigint;
  netToVendor: bigint;
  fee: bigint;
  totalPaid: bigint;
}

/**
 * Find the single `Subscribed` event for `offeringId` + `investor` among a transaction's logs.
 *
 * Filters to the offering address first, then decodes with `strict: false` so other events the
 * offering emits in the same tx (e.g. `ProceedsReleased`, which isn't in the UI ABI) are ignored
 * rather than throwing. Requires exactly one match — persistence is idempotent on (chainId,
 * txHash), so 0 or >1 would be ambiguous.
 */
export function findSubscribedEvent(
  logs: readonly Log[],
  offeringAddress: Address,
  offeringId: number,
  investor: Address,
): SubscribedArgs {
  const offeringLogs = logs.filter(
    (log) => log.address.toLowerCase() === offeringAddress.toLowerCase(),
  );
  const events = parseEventLogs({
    abi: primaryOfferingAbi,
    eventName: "Subscribed",
    logs: offeringLogs,
    strict: false,
  });

  const matches = events.filter(
    (e) =>
      e.args.offeringId === BigInt(offeringId) &&
      e.args.investor?.toLowerCase() === investor.toLowerCase(),
  );
  if (matches.length === 0) {
    throw new SettlementDecodeError(
      "No matching Subscribed event for this offering/investor in the transaction.",
    );
  }
  if (matches.length > 1) {
    throw new SettlementDecodeError(
      "Ambiguous: multiple matching Subscribed events in the transaction.",
    );
  }

  // strict:false types the decoded args as possibly-undefined; the topic filter guarantees the
  // indexed fields, but assert all are present so the return is fully typed (and a malformed log
  // that somehow matched is rejected rather than silently producing undefined amounts).
  const a = matches[0]!.args;
  if (
    a.offeringId === undefined ||
    a.investor === undefined ||
    a.quantity === undefined ||
    a.netToVendor === undefined ||
    a.fee === undefined ||
    a.totalPaid === undefined
  ) {
    throw new SettlementDecodeError("Subscribed event could not be fully decoded.");
  }
  return {
    offeringId: a.offeringId,
    investor: a.investor,
    quantity: a.quantity,
    netToVendor: a.netToVendor,
    fee: a.fee,
    totalPaid: a.totalPaid,
  };
}

