import "server-only";
import {
  ContractFunctionExecutionError,
  TransactionReceiptNotFoundError,
  createPublicClient,
  http,
  type Address,
  type Hex,
} from "viem";
import { getChain } from "@/lib/chains";
import { getOfferingAddress, primaryOfferingAbi } from "@/lib/offering/config";
import { SettlementDecodeError, findSubscribedEvent } from "@/lib/portfolio/decode";
import { RPC_URL } from "@/lib/rpcUrls";
import type { NewSettlementRecord } from "@/lib/db/settlements";

/**
 * Trust boundary for the settlement read-model. The /api/portfolio POST is public, and
 * {@link aggregateHoldings} turns its rows into holdings + cost basis, so a forged or duplicated
 * row would corrupt a subscriber's financial view. Rather than trust the client-supplied amounts,
 * this verifier re-derives the settlement straight from the on-chain `Subscribed` event: it loads
 * the transaction receipt, confirms it succeeded, finds the `Subscribed` log emitted by the
 * configured {PrimaryOffering} for the claimed offering + investor, and reads the authoritative
 * token/vendor from the contract. Only on-chain truth is persisted; the client cannot fabricate
 * a settlement that never happened.
 */

export interface SettlementClaim {
  chainId: number;
  offeringId: number;
  investor: Address;
  txHash: Hex;
}

/** Thrown when the claimed settlement cannot be verified against the chain (route → 422). */
export class SettlementVerificationError extends Error {}
/** Thrown for configuration problems (offering not wired for the chain) (route → 501). */
export class SettlementNotConfiguredError extends Error {}

export async function verifySettlement(claim: SettlementClaim): Promise<NewSettlementRecord> {
  const offeringAddress = getOfferingAddress(claim.chainId);
  if (!offeringAddress) {
    throw new SettlementNotConfiguredError(
      `No primary offering configured for chain ${claim.chainId}.`,
    );
  }
  const chain = getChain(claim.chainId);
  if (!chain) {
    throw new SettlementNotConfiguredError(`Unsupported chain ${claim.chainId}.`);
  }

  const client = createPublicClient({ chain, transport: http(RPC_URL[claim.chainId]) });

  const receipt = await client.getTransactionReceipt({ hash: claim.txHash }).catch((err) => {
    // Only a genuinely missing receipt is a client error; let transport/RPC failures bubble (→ 500)
    // so they aren't misclassified as 422 and can be retried/alerted.
    if (err instanceof TransactionReceiptNotFoundError) {
      throw new SettlementVerificationError("Transaction not found.");
    }
    throw err;
  });
  if (receipt.status !== "success") {
    throw new SettlementVerificationError("Transaction did not succeed.");
  }

  // Decode the single Subscribed event for this offering + investor (pure, unit-tested logic).
  let event;
  try {
    event = findSubscribedEvent(receipt.logs, offeringAddress, claim.offeringId, claim.investor);
  } catch (err) {
    if (err instanceof SettlementDecodeError) {
      throw new SettlementVerificationError(err.message);
    }
    throw err;
  }

  // Token + vendor are not in the event; read the authoritative values from the contract.
  // A revert here (e.g. unknown offeringId) is a verification failure, not a 500.
  const offering = await client
    .readContract({
      address: offeringAddress,
      abi: primaryOfferingAbi,
      functionName: "getOffering",
      args: [BigInt(claim.offeringId)],
    })
    .catch((err) => {
      // A contract revert (e.g. unknown offeringId) is a verification failure; transport/RPC
      // errors bubble (→ 500) instead of being masked as "Offering not found".
      if (err instanceof ContractFunctionExecutionError) {
        throw new SettlementVerificationError("Offering not found for the claimed offeringId.");
      }
      throw err;
    });

  return {
    chainId: claim.chainId,
    offeringId: claim.offeringId,
    token: offering.token,
    investor: event.investor,
    vendor: offering.vendor,
    quantity: event.quantity.toString(),
    netToVendor: event.netToVendor.toString(),
    fee: event.fee.toString(),
    totalPaid: event.totalPaid.toString(),
    txHash: claim.txHash,
  };
}

import type { Abi, Address } from "viem";
import { parseEnvAddress } from "@/lib/address";

/**
 * Primary-subscription DvP wiring for the frontend (issue #3, Epic 4).
 *
 * On-chain: {PrimaryOffering} (atomic DvP) + {MockStablecoin} (the cash leg, mocked in R1 —
 * Ctrl Alt seam #12) + the ERC-3643 Fraction Token from issue #2. Addresses are populated from
 * env after `pnpm --filter @roughnet/contracts deploy:offering:<chain>`.
 */

/** Hand-maintained ABI subset of PrimaryOffering.sol used by the UI. */
export const primaryOfferingAbi = [
  {
    type: "function",
    name: "paymentToken",
    inputs: [],
    outputs: [{ type: "address" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "quote",
    inputs: [
      { name: "offeringId", type: "uint256" },
      { name: "quantity", type: "uint256" },
    ],
    outputs: [
      { name: "netToVendor", type: "uint256" },
      { name: "fee", type: "uint256" },
      { name: "totalCost", type: "uint256" },
    ],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "subscribe",
    inputs: [
      { name: "offeringId", type: "uint256" },
      { name: "quantity", type: "uint256" },
    ],
    outputs: [],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "remaining",
    inputs: [{ name: "offeringId", type: "uint256" }],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "purchased",
    inputs: [
      { name: "offeringId", type: "uint256" },
      { name: "investor", type: "address" },
    ],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "event",
    name: "Subscribed",
    inputs: [
      { name: "offeringId", type: "uint256", indexed: true },
      { name: "investor", type: "address", indexed: true },
      { name: "quantity", type: "uint256", indexed: false },
      { name: "netToVendor", type: "uint256", indexed: false },
      { name: "fee", type: "uint256", indexed: false },
      { name: "totalPaid", type: "uint256", indexed: false },
    ],
    anonymous: false,
  },
  {
    type: "function",
    name: "getOffering",
    inputs: [{ name: "offeringId", type: "uint256" }],
    outputs: [
      {
        type: "tuple",
        components: [
          { name: "token", type: "address" },
          { name: "vendor", type: "address" },
          { name: "unitPrice", type: "uint256" },
          { name: "discountBps", type: "uint16" },
          { name: "feeBps", type: "uint16" },
          { name: "feeRecipient", type: "address" },
          { name: "cap", type: "uint256" },
          { name: "perInvestorLimit", type: "uint256" },
          { name: "sold", type: "uint256" },
          { name: "active", type: "bool" },
        ],
      },
    ],
    stateMutability: "view",
  },
] as const satisfies Abi;

/** Minimal ERC-20 ABI for the stablecoin: balance, allowance, approve, and the mock faucet. */
export const erc20Abi = [
  {
    type: "function",
    name: "balanceOf",
    inputs: [{ name: "account", type: "address" }],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "decimals",
    inputs: [],
    outputs: [{ type: "uint8" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "symbol",
    inputs: [],
    outputs: [{ type: "string" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "allowance",
    inputs: [
      { name: "owner", type: "address" },
      { name: "spender", type: "address" },
    ],
    outputs: [{ type: "uint256" }],
    stateMutability: "view",
  },
  {
    type: "function",
    name: "approve",
    inputs: [
      { name: "spender", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [{ type: "bool" }],
    stateMutability: "nonpayable",
  },
  {
    type: "function",
    name: "mint",
    inputs: [
      { name: "to", type: "address" },
      { name: "amount", type: "uint256" },
    ],
    outputs: [],
    stateMutability: "nonpayable",
  },
] as const satisfies Abi;

const OFFERING_ENV: Record<number, string | undefined> = {
  11155111: process.env.NEXT_PUBLIC_OFFERING_SEPOLIA,
  137: process.env.NEXT_PUBLIC_OFFERING_POLYGON,
  8453: process.env.NEXT_PUBLIC_OFFERING_BASE,
  31337: process.env.NEXT_PUBLIC_OFFERING_LOCAL,
};

/**
 * The PrimaryOffering address for a chain, or undefined if it isn't deployed there. This is the
 * only address that needs configuring: the stablecoin is derived on-chain from
 * `PrimaryOffering.paymentToken()` (so it can't drift from a separate env var) and the Fraction
 * Token from `getOffering()`. Settlement verification needs only this address.
 */
export function getOfferingAddress(chainId: number): Address | undefined {
  return parseEnvAddress(OFFERING_ENV[chainId]);
}

/** The demo offering id the UI subscribes to (default 0; configurable for multi-cell demos). */
const MAX_UINT256 = 2n ** 256n - 1n;
function parseOfferingId(raw: string | undefined): bigint {
  if (!raw) return 0n;
  try {
    const value = BigInt(raw);
    // Keep it a valid uint256; an out-of-range or negative misconfig falls back to 0 rather than
    // throwing later during ABI encoding.
    return value >= 0n && value <= MAX_UINT256 ? value : 0n;
  } catch {
    return 0n;
  }
}

export const defaultOfferingId = parseOfferingId(process.env.NEXT_PUBLIC_OFFERING_ID);

/**
 * Whether to show the mock-stablecoin faucet (calls `mint()`). Off by default: it only works on
 * the R1 {MockStablecoin}; a production Ctrl Alt stablecoin (issue #12) won't expose a public
 * mint, so gating it keeps the stablecoin an integration swap rather than a code change.
 */
export const stablecoinFaucetEnabled =
  process.env.NEXT_PUBLIC_ENABLE_STABLECOIN_FAUCET === "true";

