48	    json = await request.json();
49	  } catch {
50	    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
51	  }
52	
53	  const claim = parseClaim(json);
54	  if (!claim) {
55	    return NextResponse.json({ error: "Invalid record payload" }, { status: 400 });
56	  }
57	
58	  let record: Awaited<ReturnType<typeof verifyNoteUpdate>>;
59	  try {
60	    // Persist only what the chain confirms — never the client's claimed note/updatedBy.
