import "server-only";
import { NextResponse } from "next/server";

/**
 * The read-model write endpoints (/api/records, /api/portfolio) verify the claim by doing on-demand
 * RPC receipt/log lookups. They're public and unauthenticated, so on a production deployment they
 * could be abused to drive load against the RPC provider and the server. Require an explicit opt-in
 * there (same pattern as the mock KYC endpoint); dev is unrestricted. Returns a 403 response when
 * disabled, or null when the write is allowed.
 *
 * Rate limiting at the edge is still recommended on top of this for a real public deployment.
 */
export function blockedReadModelWrite(): NextResponse | null {
  if (process.env.NODE_ENV === "production" && process.env.ENABLE_READMODEL_WRITES !== "true") {
    return NextResponse.json(
      {
        error:
          "Read-model writes are disabled in production. Set ENABLE_READMODEL_WRITES=true to enable.",
      },
      { status: 403 },
    );
  }
  return null;
}

