"use client";

import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useCallback, useEffect, useState } from "react";
import { useAccount, useReadContract, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { getRegistryAddress, registryAbi } from "@/lib/contract";
import type { RegistryRecord } from "@/lib/db/repository";

export function RegistryDemo() {
  const { address, chainId, isConnected } = useAccount();
  const registry = chainId ? getRegistryAddress(chainId) : undefined;

  const [draft, setDraft] = useState("");
  const [records, setRecords] = useState<RegistryRecord[]>([]);
  const [persisted, setPersisted] = useState(false);
  const [persistError, setPersistError] = useState<string | null>(null);
  // The chain the setNote tx was submitted on, captured at submit so a mid-mining network switch
  // can't persist the record under the wrong chainId.
  const [submittedChainId, setSubmittedChainId] = useState<number | undefined>(undefined);

  const noteRead = useReadContract({
    abi: registryAbi,
    address: registry,
    functionName: "note",
    query: { enabled: Boolean(registry) },
  });

  const { writeContract, data: txHash, isPending, error: writeError } = useWriteContract();
  const receipt = useWaitForTransactionReceipt({ hash: txHash });

  const loadRecords = useCallback(async () => {
    const res = await fetch("/api/records");
    if (res.ok) {
      const json = (await res.json()) as { records: RegistryRecord[] };
      setRecords(json.records);
    }
  }, []);

  useEffect(() => {
    void loadRecords();
  }, [loadRecords]);

  // Once the tx is confirmed, persist the off-chain record (Neon) and refresh. The server
  // re-derives note + updatedBy from the on-chain NoteUpdated event, so we only send the claim.
  useEffect(() => {
    if (!receipt.isSuccess || !txHash || !submittedChainId) return;
    const claimChainId = submittedChainId;
    void (async () => {
      setPersistError(null);
      try {
        const res = await fetch("/api/records", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({ chainId: claimChainId, txHash }),
        });
        if (!res.ok) {
          const json = (await res.json().catch(() => ({}))) as { error?: string };
          setPersistError(json.error ?? `Failed to save record (${res.status}).`);
          return;
        }
        setPersisted(true);
        await noteRead.refetch();
        await loadRecords();
      } catch (err) {
        setPersistError(err instanceof Error ? err.message : "Failed to save record.");
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [receipt.isSuccess]);

  const onSubmit = () => {
    if (!registry || draft.length === 0 || !chainId) return;
    setPersisted(false);
    setPersistError(null);
    setSubmittedChainId(chainId);
    writeContract({ abi: registryAbi, address: registry, functionName: "setNote", args: [draft] });
  };

  return (
    <section className="panel">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>Update note (self-custodial wallet)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to write.</p>
      ) : !registry ? (
        <p className="muted">No registry deployed on the connected chain (chainId {chainId}).</p>
      ) : (
        <>
          <p className="muted">
            Live note: <strong>{noteRead.data ?? "…"}</strong>
          </p>
          <div className="row">
            <input
              type="text"
              value={draft}
              placeholder="New note"
              onChange={(e) => setDraft(e.target.value)}
            />
            <button onClick={onSubmit} disabled={isPending || receipt.isLoading || draft.length === 0}>
              {isPending ? "Confirm in wallet…" : receipt.isLoading ? "Mining…" : "Set note"}
            </button>
          </div>
          {writeError ? <p className="muted">⚠ {writeError.message}</p> : null}
          {persistError ? (
            <p className="muted">⚠ Confirmed on-chain, but saving to Neon failed: {persistError}</p>
          ) : persisted ? (
            <p className="muted">✓ Confirmed &amp; saved to Neon.</p>
          ) : receipt.isSuccess ? (
            <p className="muted">✓ Confirmed on-chain — saving…</p>
          ) : null}
        </>
      )}

      <h3>Persisted records (Neon read-back)</h3>
      {records.length === 0 ? (
        <p className="muted">No records yet.</p>
      ) : (
        <ul className="records">
          {records.map((r) => (
            <li key={r.id}>
              <strong>{r.note}</strong> · chain {r.chainId} ·{" "}
              <code>{r.txHash.slice(0, 10)}…</code> ·{" "}
              <span className="muted">{new Date(r.createdAt).toLocaleString()}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

