11	} from "wagmi";
12	import {
13	  defaultOfferingId,
14	  erc20Abi,
15	  getOfferingAddress,
16	  primaryOfferingAbi,
17	  stablecoinFaucetEnabled,
18	} from "@/lib/offering/config";
19	
20	/**
21	 * Primary-subscription DvP flow (issue #3, FR4.5): shows live price/discount/fees and the
22	 * connected wallet's stablecoin balance, then settles atomically — stablecoin to the Vendor and
23	 * freshly minted Fraction Tokens to the Subscriber in one transaction, or revert. The cash leg
24	 * is a mock stablecoin in R1 (Ctrl Alt seam #12); a faucet button simulates the fiat on-ramp.
25	 */
26	export function SubscriptionPanel() {
27	  const { address, chainId, isConnected } = useAccount();
28	  const offeringAddress = chainId ? getOfferingAddress(chainId) : undefined;
29	  const offeringId = defaultOfferingId;
30	  // The portfolio API records offeringId as a JS number. Realistic ids are small sequential
31	  // integers, but guard the (mis)configuration where the id can't be represented, so we never
32	  // settle on-chain and then be unable to record it.
