"use client";

import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useEffect, useMemo, useState } from "react";
import { type Address, formatUnits } from "viem";
import {
  useAccount,
  useReadContract,
  useWaitForTransactionReceipt,
  useWriteContract,
} from "wagmi";
import {
  defaultOfferingId,
  erc20Abi,
  getOfferingAddress,
  primaryOfferingAbi,
  stablecoinFaucetEnabled,
} from "@/lib/offering/config";

/**
 * Primary-subscription DvP flow (issue #3, FR4.5): shows live price/discount/fees and the
 * connected wallet's stablecoin balance, then settles atomically — stablecoin to the Vendor and
 * freshly minted Fraction Tokens to the Subscriber in one transaction, or revert. The cash leg
 * is a mock stablecoin in R1 (Ctrl Alt seam #12); a faucet button simulates the fiat on-ramp.
 */
export function SubscriptionPanel() {
  const { address, chainId, isConnected } = useAccount();
  const offeringAddress = chainId ? getOfferingAddress(chainId) : undefined;
  const offeringId = defaultOfferingId;
  // The portfolio API records offeringId as a JS number. Realistic ids are small sequential
  // integers, but guard the (mis)configuration where the id can't be represented, so we never
  // settle on-chain and then be unable to record it.
  const offeringIdRecordable = offeringId <= BigInt(Number.MAX_SAFE_INTEGER);

  const [qtyInput, setQtyInput] = useState("1");
  const quantity = useMemo(() => {
    // Accept only trimmed base-10 integer strings (BigInt would reject e.g. "1e3" by throwing).
    const trimmed = qtyInput.trim();
    if (!/^\d+$/.test(trimmed)) return 0n;
    const q = BigInt(trimmed);
    return q > 0n ? q : 0n;
  }, [qtyInput]);

  const enabled = Boolean(offeringAddress);

  const offeringRead = useReadContract({
    abi: primaryOfferingAbi,
    address: offeringAddress,
    functionName: "getOffering",
    args: [offeringId],
    query: { enabled },
  });
  // The stablecoin is the offering's payment token — read it on-chain so it can't drift from a
  // separate env var.
  const stablecoinRead = useReadContract({
    abi: primaryOfferingAbi,
    address: offeringAddress,
    functionName: "paymentToken",
    query: { enabled },
  });
  // Gate on offeringAddress: wagmi keeps the last data when a query is disabled, so without this
  // `stablecoin` could point at the previous chain's token after a chain switch / disconnect.
  const stablecoin = offeringAddress ? stablecoinRead.data : undefined;

  const decimalsRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "decimals",
    query: { enabled: Boolean(stablecoin) },
  });
  const symbolRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "symbol",
    query: { enabled: Boolean(stablecoin) },
  });
  const balanceRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "balanceOf",
    args: address ? [address] : undefined,
    query: { enabled: Boolean(stablecoin && address) },
  });
  const allowanceRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "allowance",
    args: address && offeringAddress ? [address, offeringAddress] : undefined,
    query: { enabled: Boolean(stablecoin && address && offeringAddress) },
  });
  // Read the authoritative net/fee/total from the contract itself rather than re-implementing the
  // pricing math in the UI (which could drift from PrimaryOffering._price).
  const quoteRead = useReadContract({
    abi: primaryOfferingAbi,
    address: offeringAddress,
    functionName: "quote",
    args: [offeringId, quantity],
    query: { enabled: enabled && quantity > 0n },
  });

  const offering = offeringRead.data;
  // Coerce to a JS number: formatUnits and BigInt(decimals) both need a number, not a bigint.
  const decimals = Number(decimalsRead.data ?? 6);
  const symbol = symbolRead.data ?? "mUSD";
  const balance = balanceRead.data ?? 0n;
  const allowance = allowanceRead.data ?? 0n;

  const cost = quoteRead.data
    ? { net: quoteRead.data[0], fee: quoteRead.data[1], total: quoteRead.data[2] }
    : null;
  const fmt = (v: bigint) => formatUnits(v, decimals);

  const needsApproval = Boolean(cost && cost.total > allowance);
  const insufficientBalance = Boolean(cost && cost.total > balance);

  const approve = useWriteContract();
  const approveReceipt = useWaitForTransactionReceipt({ hash: approve.data });
  const subscribe = useWriteContract();
  const subscribeReceipt = useWaitForTransactionReceipt({ hash: subscribe.data });
  const faucet = useWriteContract();
  const faucetReceipt = useWaitForTransactionReceipt({ hash: faucet.data });

  const [persistError, setPersistError] = useState<string | null>(null);
  // Snapshot of the claim context at submit time, so a mid-mining account/network switch can't
  // make us persist the settlement under the wrong investor/chain.
  type SubmittedContext = { chainId: number; investor: Address; offeringId: bigint };
  const [submitted, setSubmitted] = useState<SubmittedContext | null>(null);

  // Refresh allowance once an approval confirms.
  useEffect(() => {
    if (approveReceipt.isSuccess) void allowanceRead.refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [approveReceipt.isSuccess]);

  // Refresh balance once the faucet confirms.
  useEffect(() => {
    if (faucetReceipt.isSuccess) void balanceRead.refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [faucetReceipt.isSuccess]);

  // Once the DvP tx confirms, ask the server to record it. The server re-derives the settlement
  // from the on-chain Subscribed event, so the client only sends the claim (chain, offering,
  // investor, txHash). Only refresh + signal the portfolio when persistence actually succeeds.
  useEffect(() => {
    if (!subscribeReceipt.isSuccess || !subscribe.data || !submitted) return;
    const ctx = submitted;
    const txHash = subscribe.data;
    // The API takes offeringId as a JS number; guard the bigint->number cast so a huge id can't
    // silently lose precision and record the wrong offering.
    if (ctx.offeringId > BigInt(Number.MAX_SAFE_INTEGER)) {
      setPersistError("Offering id is too large to record.");
      return;
    }
    void (async () => {
      setPersistError(null);
      try {
        const res = await fetch("/api/portfolio", {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify({
            chainId: ctx.chainId,
            offeringId: Number(ctx.offeringId),
            investor: ctx.investor,
            txHash,
          }),
        });
        if (!res.ok) {
          const json = (await res.json().catch(() => ({}))) as { error?: string };
          setPersistError(json.error ?? `Failed to record settlement (${res.status}).`);
          return;
        }
        await Promise.all([balanceRead.refetch(), allowanceRead.refetch(), offeringRead.refetch()]);
        window.dispatchEvent(new CustomEvent("roughnet:settlement"));
      } catch (err) {
        setPersistError(err instanceof Error ? err.message : "Failed to record settlement.");
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [subscribeReceipt.isSuccess]);

  const onApprove = () => {
    if (!stablecoin || !offeringAddress || !cost) return;
    approve.writeContract({
      abi: erc20Abi,
      address: stablecoin,
      functionName: "approve",
      args: [offeringAddress, cost.total],
    });
  };

  const onSubscribe = () => {
    if (!offeringAddress || !offering || !cost || quantity === 0n || !address || !chainId) return;
    if (!offeringIdRecordable) {
      setPersistError("This offering id is too large for the app to record; subscription blocked.");
      return;
    }
    setPersistError(null);
    // Capture the investor/chain now; the tx is sent from this account on this chain.
    setSubmitted({ chainId, investor: address, offeringId });
    subscribe.writeContract({
      abi: primaryOfferingAbi,
      address: offeringAddress,
      functionName: "subscribe",
      args: [offeringId, quantity],
    });
  };

  const onFaucet = () => {
    if (!stablecoin || !address) return;
    // Mint enough to cover the current order (simulated fiat on-ramp); when no quote is available
    // yet, fall back to a fixed default so the faucet still works.
    const amount = cost && cost.total > 0n ? cost.total : 1000n * 10n ** BigInt(decimals);
    faucet.writeContract({
      abi: erc20Abi,
      address: stablecoin,
      functionName: "mint",
      args: [address, amount],
    });
  };

  return (
    <section className="panel">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>Subscribe — primary offering (atomic DvP)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to subscribe.</p>
      ) : !offeringAddress ? (
        <p className="muted">No primary offering deployed on the connected chain (chainId {chainId}).</p>
      ) : offeringRead.isLoading ? (
        <p className="muted">Loading offering…</p>
      ) : !offering ? (
        <p className="muted">⚠ Offering #{offeringId.toString()} not found.</p>
      ) : (
        <>
          <p className="muted">
            Unit price: <strong>{fmt(offering.unitPrice)} {symbol}</strong>
            {offering.discountBps > 0 ? <> · discount {Number(offering.discountBps) / 100}%</> : null}
            {offering.feeBps > 0 ? <> · fee {Number(offering.feeBps) / 100}%</> : null}
            {" · "}sold {offering.sold.toString()}/{offering.cap.toString()}
            {!offering.active ? <> · <strong>closed</strong></> : null}
          </p>
          <p className="muted">
            Your stablecoin balance: <strong>{fmt(balance)} {symbol}</strong>{" "}
            {stablecoinFaucetEnabled ? (
              <button onClick={onFaucet} disabled={faucet.isPending || faucetReceipt.isLoading}>
                {faucet.isPending || faucetReceipt.isLoading ? "Funding…" : `Get mock ${symbol}`}
              </button>
            ) : null}
          </p>

          <div className="row">
            <label>
              Quantity (fractions){" "}
              <input
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                value={qtyInput}
                // Constrain to digits so the input matches the base-10 parsing (a number input
                // would allow "1e6", which would silently parse to 0).
                onChange={(e) => setQtyInput(e.target.value.replace(/[^0-9]/g, ""))}
              />
            </label>
          </div>

          {cost ? (
            <ul className="records">
              <li>Net to vendor: <strong>{fmt(cost.net)} {symbol}</strong></li>
              <li>Platform fee: <strong>{fmt(cost.fee)} {symbol}</strong></li>
              <li>You pay (DvP total): <strong>{fmt(cost.total)} {symbol}</strong></li>
            </ul>
          ) : null}

          {quoteRead.error && quantity > 0n ? (
            <p className="muted">⚠ {quoteRead.error.message}</p>
          ) : null}

          {insufficientBalance ? (
            <p className="muted">
              ⚠ Insufficient stablecoin{stablecoinFaucetEnabled ? " — use the faucet above." : "."}
            </p>
          ) : null}

          <div className="row">
            {needsApproval ? (
              <button
                onClick={onApprove}
                disabled={
                  quantity === 0n || approve.isPending || approveReceipt.isLoading || insufficientBalance
                }
              >
                {approve.isPending
                  ? "Confirm approval…"
                  : approveReceipt.isLoading
                    ? "Approving…"
                    : "Approve stablecoin"}
              </button>
            ) : (
              <button
                onClick={onSubscribe}
                disabled={
                  quantity === 0n ||
                  !cost ||
                  !offering.active ||
                  !offeringIdRecordable ||
                  subscribe.isPending ||
                  subscribeReceipt.isLoading ||
                  insufficientBalance
                }
              >
                {subscribe.isPending
                  ? "Confirm in wallet…"
                  : subscribeReceipt.isLoading
                    ? "Settling DvP…"
                    : "Subscribe (swap cash ↔ tokens)"}
              </button>
            )}
          </div>

          {approve.error ? <p className="muted">⚠ {approve.error.message}</p> : null}
          {subscribe.error ? <p className="muted">⚠ {subscribe.error.message}</p> : null}
          {persistError ? (
            <p className="muted">
              ⚠ DvP settled on-chain, but recording it failed: {persistError}
            </p>
          ) : subscribeReceipt.isSuccess ? (
            <p className="muted">✓ DvP settled — tokens delivered, vendor paid, portfolio updated.</p>
          ) : null}
          <p className="muted">
            Not whitelisted yet? Run mock KYC above first — the delivery leg reverts (and your cash
            stays put) until your wallet is verified.
          </p>
        </>
      )}
    </section>
  );
}

