import "server-only";
import { InMemoryRecordsRepository, InMemorySettlementsRepository } from "./memory";
import { NeonRecordsRepository, NeonSettlementsRepository } from "./neon";
import type { RecordsRepository } from "./repository";
import type { SettlementsRepository } from "./settlements";

export type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";
export type { NewSettlementRecord, SettlementRecord, SettlementsRepository } from "./settlements";

let singleton: RecordsRepository | undefined;
let settlementsSingleton: SettlementsRepository | undefined;

/**
 * Returns the process-wide records repository: Neon when DATABASE_URL is set,
 * otherwise an in-memory fallback (non-persistent — fine for local dev/tests).
 */
export function getRecordsRepository(): RecordsRepository {
  if (singleton) return singleton;

  const url = process.env.DATABASE_URL;
  if (url) {
    singleton = new NeonRecordsRepository(url);
  } else {
    if (process.env.NODE_ENV === "production") {
      console.warn(
        "[db] DATABASE_URL is not set — using in-memory store. Records will NOT persist.",
      );
    }
    singleton = new InMemoryRecordsRepository();
  }
  return singleton;
}

/**
 * Returns the process-wide settlements repository: Neon when DATABASE_URL is set, otherwise an
 * in-memory fallback (non-persistent — fine for local dev/tests).
 */
export function getSettlementsRepository(): SettlementsRepository {
  if (settlementsSingleton) return settlementsSingleton;

  const url = process.env.DATABASE_URL;
  if (url) {
    settlementsSingleton = new NeonSettlementsRepository(url);
  } else {
    if (process.env.NODE_ENV === "production") {
      console.warn(
        "[db] DATABASE_URL is not set — using in-memory settlements store. Settlements will NOT persist.",
      );
    }
    settlementsSingleton = new InMemorySettlementsRepository();
  }
  return settlementsSingleton;
}

