/**
 * Off-chain primary-subscription settlement read-model (BRD FR4.3/FR4.6; ADR-0006: Neon).
 *
 * One row per confirmed DvP subscription, mirroring the on-chain {Subscribed} event. The
 * portfolio (holdings + cost basis + settlement history) is derived from these rows. As with
 * the Register read-model, everything depends on this interface, never on a concrete driver,
 * so the in-memory fallback and the Neon implementation are interchangeable.
 */
import type { Holding } from "@/lib/portfolio/holdings";

export type { Holding };

export interface SettlementRecord {
  id: number;
  chainId: number;
  offeringId: number;
  /** ERC-3643 Fraction Token series address. */
  token: string;
  /** Subscriber wallet (lowercased on write for stable lookups). */
  investor: string;
  vendor: string;
  /** Fractions delivered (token decimals = 0), as a decimal integer string. */
  quantity: string;
  /** Stablecoin smallest-units paid to the vendor, as a decimal integer string. */
  netToVendor: string;
  /** Stablecoin platform fee, as a decimal integer string. */
  fee: string;
  /** Total stablecoin paid by the subscriber (netToVendor + fee). */
  totalPaid: string;
  txHash: string;
  /** ISO-8601 timestamp. */
  createdAt: string;
}

export type NewSettlementRecord = Omit<SettlementRecord, "id" | "createdAt">;

/** Filter for {@link SettlementsRepository.list}. Each field narrows independently. */
export interface SettlementsFilter {
  /** Wallet address (matched case-insensitively). */
  investor?: string;
  /** Chain id — portfolio views are chain-scoped so positions don't mix across networks. */
  chainId?: number;
}

export interface SettlementsRepository {
  /** Insert a settlement and return the persisted row (with id + createdAt). */
  add(record: NewSettlementRecord): Promise<SettlementRecord>;
  /** Return settlements newest first, optionally narrowed by investor and/or chainId. */
  list(filter?: SettlementsFilter, limit?: number): Promise<SettlementRecord[]>;
  /**
   * Per-token holdings (quantity + cost basis) aggregated over the *entire* filtered history.
   * Computed DB-side where possible so holdings stay correct without paging the full history into
   * memory.
   */
  sumHoldings(filter?: SettlementsFilter): Promise<Holding[]>;
}

