import { base, polygon, sepolia, type Chain } from "viem/chains";

/** Local anvil/hardhat devnet. */
export const localDevnet = {
  id: 31337,
  name: "Local Devnet",
  nativeCurrency: { name: "Ether", symbol: "ETH", decimals: 18 },
  rpcUrls: { default: { http: ["http://127.0.0.1:8545"] } },
} as const satisfies Chain;

/** Chains the app understands. Sepolia is the dev/test default (ADR-0006). */
export const supportedChains = [sepolia, polygon, base, localDevnet] as const;

/**
 * Parse NEXT_PUBLIC_CHAIN_ID, falling back to Sepolia when unset, invalid, or not one of the
 * supported chains — so defaultChainId and defaultChain can't disagree (e.g. "chainId 10 /
 * chainName Sepolia") and address lookups keyed by defaultChainId stay consistent.
 */
function parseChainId(raw: string | undefined): number {
  if (raw === undefined || raw === "") return sepolia.id;
  const value = Number(raw);
  if (!Number.isInteger(value) || value <= 0) return sepolia.id;
  return supportedChains.some((c) => c.id === value) ? value : sepolia.id;
}

export const defaultChainId = parseChainId(process.env.NEXT_PUBLIC_CHAIN_ID);

export function getChain(chainId: number): Chain | undefined {
  return supportedChains.find((c) => c.id === chainId);
}

export const defaultChain: Chain =
  getChain(defaultChainId) ?? sepolia;

