import { describe, expect, it } from "vitest";
// Value-import via the `@/` alias (not just a type import) so this also covers the Vitest alias.
import { aggregateHoldings } from "@/lib/portfolio/holdings";
import type { SettlementRecord } from "@/lib/db/settlements";

const TOKEN_A = "0xAAaAAA0000000000000000000000000000000001";
const TOKEN_B = "0xBbBBbB0000000000000000000000000000000002";

const settlement = (overrides: Partial<SettlementRecord> = {}): SettlementRecord => ({
  id: 1,
  chainId: 11155111,
  offeringId: 0,
  token: TOKEN_A,
  investor: "0x0000000000000000000000000000000000000abc",
  vendor: "0x000000000000000000000000000000000000beef",
  quantity: "10",
  netToVendor: "1000000000", // 1000 mUSD (6dp)
  fee: "0",
  totalPaid: "1000000000",
  txHash: "0xabc",
  createdAt: "2026-06-21T00:00:00.000Z",
  ...overrides,
});

describe("aggregateHoldings", () => {
  it("returns no holdings for an empty list", () => {
    expect(aggregateHoldings([])).toEqual([]);
  });

  it("sums quantity and cost across settlements of the same token", () => {
    const holdings = aggregateHoldings([
      settlement({ quantity: "10", totalPaid: "1000000000" }),
      settlement({ quantity: "5", totalPaid: "450000000" }),
    ]);

    expect(holdings).toHaveLength(1);
    expect(holdings[0]).toMatchObject({
      token: TOKEN_A.toLowerCase(),
      quantity: "15",
      totalCost: "1450000000",
    });
  });

  it("computes cost basis as floor(totalCost / quantity)", () => {
    // 1450 mUSD over 15 fractions = 96.666… -> floor at smallest unit.
    const holdings = aggregateHoldings([
      settlement({ quantity: "10", totalPaid: "1000000000" }),
      settlement({ quantity: "5", totalPaid: "450000000" }),
    ]);

    expect(holdings[0]!.avgUnitCost).toBe("96666666");
  });

  it("groups by token case-insensitively", () => {
    const holdings = aggregateHoldings([
      settlement({ token: TOKEN_A.toLowerCase(), quantity: "1", totalPaid: "100" }),
      settlement({ token: TOKEN_A.toUpperCase(), quantity: "2", totalPaid: "200" }),
    ]);

    expect(holdings).toHaveLength(1);
    expect(holdings[0]!.quantity).toBe("3");
  });

  it("keeps distinct tokens separate, ordered by total cost desc", () => {
    const holdings = aggregateHoldings([
      settlement({ token: TOKEN_A, quantity: "1", totalPaid: "100" }),
      settlement({ token: TOKEN_B, quantity: "1", totalPaid: "900" }),
    ]);

    expect(holdings.map((h) => h.token)).toEqual([
      TOKEN_B.toLowerCase(),
      TOKEN_A.toLowerCase(),
    ]);
  });
});

