10	/**
11	 * In-memory fallback used in tests and for local dev when no DATABASE_URL is set.
12	 * Implements the same contract as the Neon-backed repository.
13	 */
14	export class InMemoryRecordsRepository implements RecordsRepository {
15	  private records: RegistryRecord[] = [];
16	  private nextId = 1;
17	
18	  async add(record: NewRegistryRecord): Promise<RegistryRecord> {
19	    // Idempotent on (chainId, txHash): a retried persist of the same note update returns the
20	    // existing row instead of duplicating it.
21	    const existing = this.records.find(
22	      (r) => r.chainId === record.chainId && r.txHash.toLowerCase() === record.txHash.toLowerCase(),
23	    );
24	    if (existing) return existing;
25	
26	    const saved: RegistryRecord = {
27	      id: this.nextId++,
28	      createdAt: new Date().toISOString(),
29	      ...record,
30	      txHash: record.txHash.toLowerCase(),
31	    };
32	    this.records.push(saved);
33	    return saved;
34	  }
35	
36	  async list(limit = 50): Promise<RegistryRecord[]> {
37	    return [...this.records].reverse().slice(0, limit);
38	  }
39	}
40	
41	/**
42	 * In-memory fallback for the primary-subscription settlement read-model. Same contract as the
43	 * Neon-backed repository; used in tests and local dev when no DATABASE_URL is set.
44	 */
45	export class InMemorySettlementsRepository implements SettlementsRepository {
46	  private records: SettlementRecord[] = [];
