import type { NewRegistryRecord, RecordsRepository, RegistryRecord } from "./repository";
import { type Holding, aggregateHoldings } from "@/lib/portfolio/holdings";
import type {
  NewSettlementRecord,
  SettlementRecord,
  SettlementsFilter,
  SettlementsRepository,
} from "./settlements";

/**
 * In-memory fallback used in tests and for local dev when no DATABASE_URL is set.
 * Implements the same contract as the Neon-backed repository.
 */
export class InMemoryRecordsRepository implements RecordsRepository {
  private records: RegistryRecord[] = [];
  private nextId = 1;

  async add(record: NewRegistryRecord): Promise<RegistryRecord> {
    // Idempotent on (chainId, txHash): a retried persist of the same note update returns the
    // existing row instead of duplicating it.
    const existing = this.records.find(
      (r) => r.chainId === record.chainId && r.txHash.toLowerCase() === record.txHash.toLowerCase(),
    );
    if (existing) return existing;

    const saved: RegistryRecord = {
      id: this.nextId++,
      createdAt: new Date().toISOString(),
      ...record,
      txHash: record.txHash.toLowerCase(),
    };
    this.records.push(saved);
    return saved;
  }

  async list(limit = 50): Promise<RegistryRecord[]> {
    return [...this.records].reverse().slice(0, limit);
  }
}

/**
 * In-memory fallback for the primary-subscription settlement read-model. Same contract as the
 * Neon-backed repository; used in tests and local dev when no DATABASE_URL is set.
 */
export class InMemorySettlementsRepository implements SettlementsRepository {
  private records: SettlementRecord[] = [];
  private nextId = 1;

  async add(record: NewSettlementRecord): Promise<SettlementRecord> {
    // Idempotent on (chainId, txHash): one DvP tx = one settlement, so a retried persist of the
    // same confirmed subscription returns the existing row instead of double-counting holdings.
    const existing = this.records.find(
      (r) => r.chainId === record.chainId && r.txHash.toLowerCase() === record.txHash.toLowerCase(),
    );
    if (existing) return existing;

    const saved: SettlementRecord = {
      id: this.nextId++,
      createdAt: new Date().toISOString(),
      ...record,
      token: record.token.toLowerCase(),
      investor: record.investor.toLowerCase(),
      vendor: record.vendor.toLowerCase(),
      txHash: record.txHash.toLowerCase(),
    };
    this.records.push(saved);
    return saved;
  }

  async list(filter: SettlementsFilter = {}, limit = 100): Promise<SettlementRecord[]> {
    return this.match(filter).reverse().slice(0, limit);
  }

  async sumHoldings(filter: SettlementsFilter = {}): Promise<Holding[]> {
    // Aggregate over the entire matching history (no page cap), mirroring the Neon DB-side sum.
    return aggregateHoldings(this.match(filter));
  }

  private match(filter: SettlementsFilter): SettlementRecord[] {
    const wanted = filter.investor?.toLowerCase();
    return this.records
      .filter((r) => (wanted ? r.investor === wanted : true))
      .filter((r) => (filter.chainId !== undefined ? r.chainId === filter.chainId : true));
  }
}

