    const txHash = record.txHash.toLowerCase();
    const token = record.token.toLowerCase();
    const investor = record.investor.toLowerCase();
    const vendor = record.vendor.toLowerCase();
    const inserted = (await this.sql`
      INSERT INTO subscription_settlements
        (chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee, total_paid, tx_hash)
      VALUES
        (${record.chainId}, ${record.offeringId}, ${token}, ${investor},
         ${vendor}, ${record.quantity}, ${record.netToVendor}, ${record.fee},
         ${record.totalPaid}, ${txHash})
      ON CONFLICT (chain_id, tx_hash) DO NOTHING
      RETURNING id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
                total_paid, tx_hash, created_at
    `) as RawSettlementRow[];
    if (inserted[0]) return toSettlement(inserted[0]);

    // Conflict: the settlement already exists — return the persisted row.
    const existing = (await this.sql`
      SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
             total_paid, tx_hash, created_at
      FROM subscription_settlements
      WHERE chain_id = ${record.chainId} AND tx_hash = ${txHash}
    `) as RawSettlementRow[];
    return toSettlement(existing[0]!);
  }

  async list(filter: SettlementsFilter = {}, limit = 100): Promise<SettlementRecord[]> {
    await this.ensureSchema();
    const investor = filter.investor?.toLowerCase();
    const { chainId } = filter;

    let rows: RawSettlementRow[];
    if (investor !== undefined && chainId !== undefined) {
      rows = (await this.sql`
        SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
               total_paid, tx_hash, created_at
        FROM subscription_settlements
        WHERE investor = ${investor} AND chain_id = ${chainId}
        ORDER BY id DESC LIMIT ${limit}
      `) as RawSettlementRow[];
    } else if (investor !== undefined) {
      rows = (await this.sql`
        SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
               total_paid, tx_hash, created_at
        FROM subscription_settlements
        WHERE investor = ${investor}
        ORDER BY id DESC LIMIT ${limit}
      `) as RawSettlementRow[];
    } else if (chainId !== undefined) {
      rows = (await this.sql`
        SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
               total_paid, tx_hash, created_at
        FROM subscription_settlements
        WHERE chain_id = ${chainId}
        ORDER BY id DESC LIMIT ${limit}
      `) as RawSettlementRow[];
    } else {
      rows = (await this.sql`
        SELECT id, chain_id, offering_id, token, investor, vendor, quantity, net_to_vendor, fee,
               total_paid, tx_hash, created_at
        FROM subscription_settlements
        ORDER BY id DESC LIMIT ${limit}
      `) as RawSettlementRow[];
    }
    return rows.map(toSettlement);
  }

  async sumHoldings(filter: SettlementsFilter = {}): Promise<Holding[]> {
    await this.ensureSchema();
    const investor = filter.investor?.toLowerCase();
    const { chainId } = filter;

    // DB-side aggregation: SUM per token over the entire matching history, so holdings stay
    // correct without paging every settlement into app memory.
    let rows: SumRow[];
    if (investor !== undefined && chainId !== undefined) {
      rows = (await this.sql`
        SELECT token, SUM(quantity) AS quantity, SUM(total_paid) AS total_cost
        FROM subscription_settlements
        WHERE investor = ${investor} AND chain_id = ${chainId}
        GROUP BY token
      `) as SumRow[];
    } else if (investor !== undefined) {
      rows = (await this.sql`
        SELECT token, SUM(quantity) AS quantity, SUM(total_paid) AS total_cost
        FROM subscription_settlements
        WHERE investor = ${investor}
        GROUP BY token
      `) as SumRow[];
    } else if (chainId !== undefined) {
      rows = (await this.sql`
        SELECT token, SUM(quantity) AS quantity, SUM(total_paid) AS total_cost
        FROM subscription_settlements
        WHERE chain_id = ${chainId}
        GROUP BY token
      `) as SumRow[];
    } else {
      rows = (await this.sql`
        SELECT token, SUM(quantity) AS quantity, SUM(total_paid) AS total_cost
        FROM subscription_settlements
        GROUP BY token
      `) as SumRow[];
    }

    return finalizeHoldings(
      rows.map((r) => ({
        token: r.token,
        quantity: BigInt(r.quantity),
        totalCost: BigInt(r.total_cost),
      })),
    );
  }
}

interface SumRow {
  token: string;
  quantity: string;
  total_cost: string;
}

