import { describe, expect, it } from "vitest";
import {
  type Address,
  type Log,
  encodeAbiParameters,
  encodeEventTopics,
} from "viem";
import { SettlementDecodeError, findSubscribedEvent } from "./decode";
import { primaryOfferingAbi } from "@/lib/offering/config";

const OFFERING: Address = "0x1111111111111111111111111111111111111111";
const OTHER_ADDR: Address = "0x9999999999999999999999999999999999999999";
const INVESTOR: Address = "0x2222222222222222222222222222222222222222";

const fields = {
  blockHash: "0x".padEnd(66, "a") as `0x${string}`,
  blockNumber: 1n,
  logIndex: 0,
  transactionHash: "0x".padEnd(66, "b") as `0x${string}`,
  transactionIndex: 0,
  removed: false,
};

function subscribedLog(
  args: {
    offeringId: bigint;
    investor: Address;
    quantity: bigint;
    netToVendor: bigint;
    fee: bigint;
    totalPaid: bigint;
  },
  address: Address = OFFERING,
): Log {
  const topics = encodeEventTopics({
    abi: primaryOfferingAbi,
    eventName: "Subscribed",
    args: { offeringId: args.offeringId, investor: args.investor },
  });
  const data = encodeAbiParameters(
    [{ type: "uint256" }, { type: "uint256" }, { type: "uint256" }, { type: "uint256" }],
    [args.quantity, args.netToVendor, args.fee, args.totalPaid],
  );
  return { ...fields, address, topics, data } as unknown as Log;
}

// ProceedsReleased is emitted by PrimaryOffering.subscribe() but is NOT in the UI ABI — it must be
// ignored by the decoder rather than causing a throw.
const proceedsAbi = [
  {
    type: "event",
    name: "ProceedsReleased",
    inputs: [
      { name: "offeringId", type: "uint256", indexed: true },
      { name: "vendor", type: "address", indexed: true },
      { name: "investor", type: "address", indexed: true },
      { name: "amount", type: "uint256", indexed: false },
    ],
    anonymous: false,
  },
] as const;

function proceedsReleasedLog(offeringId: bigint, investor: Address): Log {
  const topics = encodeEventTopics({
    abi: proceedsAbi,
    eventName: "ProceedsReleased",
    args: { offeringId, vendor: OTHER_ADDR, investor },
  });
  const data = encodeAbiParameters([{ type: "uint256" }], [1000n]);
  return { ...fields, address: OFFERING, topics, data } as unknown as Log;
}

const baseArgs = {
  offeringId: 0n,
  investor: INVESTOR,
  quantity: 10n,
  netToVendor: 1000n,
  fee: 0n,
  totalPaid: 1000n,
};

describe("findSubscribedEvent", () => {
  it("returns the Subscribed args, ignoring the offering's ProceedsReleased log", () => {
    const logs = [proceedsReleasedLog(0n, INVESTOR), subscribedLog(baseArgs)];

    const args = findSubscribedEvent(logs, OFFERING, 0, INVESTOR);

    expect(args.quantity).toBe(10n);
    expect(args.netToVendor).toBe(1000n);
    expect(args.totalPaid).toBe(1000n);
    expect(args.investor.toLowerCase()).toBe(INVESTOR.toLowerCase());
  });

  it("matches investor case-insensitively", () => {
    const logs = [subscribedLog(baseArgs)];
    const args = findSubscribedEvent(logs, OFFERING, 0, INVESTOR.toUpperCase() as Address);
    expect(args.quantity).toBe(10n);
  });

  it("throws when there is no matching Subscribed event", () => {
    const logs = [proceedsReleasedLog(0n, INVESTOR)];
    expect(() => findSubscribedEvent(logs, OFFERING, 0, INVESTOR)).toThrow(SettlementDecodeError);
  });

  it("throws when the Subscribed event is for a different investor/offering", () => {
    const logs = [subscribedLog({ ...baseArgs, offeringId: 5n })];
    expect(() => findSubscribedEvent(logs, OFFERING, 0, INVESTOR)).toThrow(SettlementDecodeError);
  });

  it("ignores Subscribed logs emitted by a different address", () => {
    const logs = [subscribedLog(baseArgs, OTHER_ADDR)];
    expect(() => findSubscribedEvent(logs, OFFERING, 0, INVESTOR)).toThrow(SettlementDecodeError);
  });

  it("throws (ambiguous) when more than one matching Subscribed event exists", () => {
    const logs = [subscribedLog(baseArgs), subscribedLog(baseArgs)];
    expect(() => findSubscribedEvent(logs, OFFERING, 0, INVESTOR)).toThrow(/Ambiguous/);
  });
});

