import { describe, expect, it } from "vitest";
import { InMemorySettlementsRepository } from "./memory";
import type { NewSettlementRecord } from "./settlements";

const sample = (overrides: Partial<NewSettlementRecord> = {}): NewSettlementRecord => ({
  chainId: 11155111,
  offeringId: 0,
  token: "0x00000000000000000000000000000000000000aa",
  investor: "0x000000000000000000000000000000000000ABCD",
  vendor: "0x000000000000000000000000000000000000beef",
  quantity: "10",
  netToVendor: "1000000000",
  fee: "0",
  totalPaid: "1000000000",
  txHash: "0xabc",
  ...overrides,
});

describe("InMemorySettlementsRepository", () => {
  it("persists a settlement and lowercases the investor", async () => {
    const repo = new InMemorySettlementsRepository();

    const saved = await repo.add(sample());

    expect(saved.id).toBeGreaterThan(0);
    expect(saved.investor).toBe("0x000000000000000000000000000000000000abcd");
    expect(saved.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });

  it("returns settlements newest first", async () => {
    const repo = new InMemorySettlementsRepository();
    await repo.add(sample({ txHash: "0x1" }));
    await repo.add(sample({ txHash: "0x2" }));

    const all = await repo.list();
    expect(all.map((r) => r.txHash)).toEqual(["0x2", "0x1"]);
  });

  it("filters by investor case-insensitively", async () => {
    const repo = new InMemorySettlementsRepository();
    await repo.add(sample({ investor: "0xAAA0000000000000000000000000000000000001", txHash: "0xa" }));
    await repo.add(sample({ investor: "0xBBB0000000000000000000000000000000000002", txHash: "0xb" }));

    const mine = await repo.list({ investor: "0xaaa0000000000000000000000000000000000001" });
    expect(mine).toHaveLength(1);
    expect(mine[0]!.txHash).toBe("0xa");
  });

  it("scopes by chainId so positions don't mix across networks", async () => {
    const repo = new InMemorySettlementsRepository();
    const investor = "0xAAA0000000000000000000000000000000000001";
    await repo.add(sample({ investor, chainId: 11155111, txHash: "0xa" }));
    await repo.add(sample({ investor, chainId: 137, txHash: "0xb" }));

    const sepoliaOnly = await repo.list({ investor, chainId: 11155111 });
    expect(sepoliaOnly.map((r) => r.txHash)).toEqual(["0xa"]);

    const both = await repo.list({ investor });
    expect(both).toHaveLength(2);
  });

  it("is idempotent on (chainId, txHash) so a retried persist can't double-count", async () => {
    const repo = new InMemorySettlementsRepository();

    const first = await repo.add(sample({ txHash: "0xdup" }));
    const second = await repo.add(sample({ txHash: "0xdup", quantity: "999" }));

    expect(second.id).toBe(first.id);
    expect(second.quantity).toBe(first.quantity); // original row, not the re-sent payload
    expect(await repo.list()).toHaveLength(1);
  });

  it("dedupes regardless of txHash casing", async () => {
    const repo = new InMemorySettlementsRepository();

    const first = await repo.add(sample({ txHash: "0xAbC123" }));
    const second = await repo.add(sample({ txHash: "0xabc123" }));

    expect(second.id).toBe(first.id);
    expect(first.txHash).toBe("0xabc123"); // stored normalized
    expect(await repo.list()).toHaveLength(1);
  });

  it("treats the same txHash on a different chain as distinct", async () => {
    const repo = new InMemorySettlementsRepository();

    await repo.add(sample({ chainId: 11155111, txHash: "0xsame" }));
    await repo.add(sample({ chainId: 137, txHash: "0xsame" }));

    expect(await repo.list()).toHaveLength(2);
  });

  it("sumHoldings aggregates the full history (ignoring the list page cap) per chain", async () => {
    const repo = new InMemorySettlementsRepository();
    const investor = "0xAAA0000000000000000000000000000000000001";
    const token = "0x00000000000000000000000000000000000000aa";
    // 150 settlements > the default 100-row list cap.
    for (let i = 0; i < 150; i++) {
      await repo.add(
        sample({ investor, token, quantity: "1", totalPaid: "10", txHash: `0x${i}` }),
      );
    }
    // A different chain must not leak into the aggregate.
    await repo.add(sample({ investor, token, chainId: 137, quantity: "999", totalPaid: "9", txHash: "0xz" }));

    const holdings = await repo.sumHoldings({ investor, chainId: 11155111 });
    expect(holdings).toHaveLength(1);
    expect(holdings[0]!.quantity).toBe("150"); // all 150, not capped at 100
    expect(holdings[0]!.totalCost).toBe("1500");
  });

  it("sumHoldings treats mixed-case token addresses as one holding", async () => {
    const repo = new InMemorySettlementsRepository();
    const investor = "0xAAA0000000000000000000000000000000000001";
    await repo.add(sample({ investor, token: "0xAbCdEf0000000000000000000000000000000001", quantity: "2", totalPaid: "20", txHash: "0x1" }));
    await repo.add(sample({ investor, token: "0xabcdef0000000000000000000000000000000001", quantity: "3", totalPaid: "30", txHash: "0x2" }));

    const holdings = await repo.sumHoldings({ investor, chainId: 11155111 });
    expect(holdings).toHaveLength(1);
    expect(holdings[0]!.quantity).toBe("5");
    expect(holdings[0]!.token).toBe("0xabcdef0000000000000000000000000000000001");
  });

  it("respects the limit argument", async () => {
    const repo = new InMemorySettlementsRepository();
    await repo.add(sample({ txHash: "0x1" }));
    await repo.add(sample({ txHash: "0x2" }));
    await repo.add(sample({ txHash: "0x3" }));

    const limited = await repo.list(undefined, 2);
    expect(limited.map((r) => r.txHash)).toEqual(["0x3", "0x2"]);
  });
});

