import { describe, expect, it } from "vitest";
import { InMemoryRecordsRepository } from "./memory";
import type { NewRegistryRecord } from "./repository";

const sample = (overrides: Partial<NewRegistryRecord> = {}): NewRegistryRecord => ({
  chainId: 11155111,
  note: "tracer",
  txHash: "0xabc",
  updatedBy: "0x0000000000000000000000000000000000000001",
  ...overrides,
});

describe("InMemoryRecordsRepository", () => {
  it("persists a record and reads it back", async () => {
    const repo = new InMemoryRecordsRepository();

    const saved = await repo.add(sample({ note: "hello" }));

    expect(saved.id).toBeGreaterThan(0);
    expect(saved.note).toBe("hello");
    expect(saved.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const all = await repo.list();
    expect(all).toHaveLength(1);
    expect(all[0]).toEqual(saved);
  });

  it("returns records newest first", async () => {
    const repo = new InMemoryRecordsRepository();

    await repo.add(sample({ note: "first", txHash: "0x1" }));
    await repo.add(sample({ note: "second", txHash: "0x2" }));

    const all = await repo.list();
    expect(all.map((r) => r.note)).toEqual(["second", "first"]);
  });

  it("assigns monotonically increasing ids", async () => {
    const repo = new InMemoryRecordsRepository();

    const a = await repo.add(sample({ txHash: "0x1" }));
    const b = await repo.add(sample({ txHash: "0x2" }));

    expect(b.id).toBe(a.id + 1);
  });

  it("is idempotent on (chainId, txHash) so a retried persist can't duplicate", async () => {
    const repo = new InMemoryRecordsRepository();

    const first = await repo.add(sample({ note: "original", txHash: "0xdup" }));
    const second = await repo.add(sample({ note: "resent", txHash: "0xdup" }));

    expect(second.id).toBe(first.id);
    expect(second.note).toBe("original");
    expect(await repo.list()).toHaveLength(1);
  });

  it("dedupes regardless of txHash casing", async () => {
    const repo = new InMemoryRecordsRepository();

    const first = await repo.add(sample({ note: "original", txHash: "0xAbC123" }));
    const second = await repo.add(sample({ note: "resent", txHash: "0xabc123" }));

    expect(second.id).toBe(first.id);
    expect(first.txHash).toBe("0xabc123"); // stored normalized
    expect(await repo.list()).toHaveLength(1);
  });

  it("respects the limit argument", async () => {
    const repo = new InMemoryRecordsRepository();

    await repo.add(sample({ note: "a", txHash: "0x1" }));
    await repo.add(sample({ note: "b", txHash: "0x2" }));
    await repo.add(sample({ note: "c", txHash: "0x3" }));

    const limited = await repo.list(2);
    expect(limited.map((r) => r.note)).toEqual(["c", "b"]);
  });
});

