toolUseResult.originalFile:
import type { SettlementRecord } from "@/lib/db/settlements";

/**
 * A Subscriber's net position in one Fraction Token series, derived from settlement
 * events (the primary-subscription read-model for FR4.6).
 *
 * All numeric fields are decimal strings of integers (wei-style) to avoid float drift:
 * `quantity` is in whole fractions (token decimals = 0), `totalCost` / `avgUnitCost` are in
 * the stablecoin's smallest unit. The UI formats them with the stablecoin's decimals.
 */
export interface Holding {
  token: string;
  quantity: string;
  /** Total stablecoin actually paid for this position (sum of totalPaid). */
  totalCost: string;
  /** Cost basis per fraction = floor(totalCost / quantity). */
  avgUnitCost: string;
}

/** A per-token summed position before formatting (quantity + total cost as bigints). */
export interface TokenTotal {
  token: string;
  quantity: bigint;
  totalCost: bigint;
}

/**
 * Format pre-summed per-token totals into Holdings: lowercase the token, compute cost basis as
 * floor(totalCost / quantity), and sort by total cost desc (token tie-break) for stable rendering.
 * Shared by {@link aggregateHoldings} (in-memory) and the Neon DB-side aggregation so both produce
 * identical output.
 */
export function finalizeHoldings(totals: TokenTotal[]): Holding[] {
  const holdings: Holding[] = totals.map((t) => ({
    token: t.token.toLowerCase(),
    quantity: t.quantity.toString(),
    totalCost: t.totalCost.toString(),
    avgUnitCost: (t.quantity > 0n ? t.totalCost / t.quantity : 0n).toString(),
  }));

  holdings.sort((a, b) => {
    const delta = BigInt(b.totalCost) - BigInt(a.totalCost);
    if (delta !== 0n) return delta > 0n ? 1 : -1;
    // Tie-break on token address so equal-cost holdings have a stable, deterministic order.
    return a.token < b.token ? -1 : a.token > b.token ? 1 : 0;
  });
  return holdings;
}

/**
 * Aggregate a flat list of settlements into per-token holdings with cost basis.
 * Token addresses are compared case-insensitively and reported lowercased.
 */
export function aggregateHoldings(settlements: SettlementRecord[]): Holding[] {
  const byToken = new Map<string, TokenTotal>();

  for (const s of settlements) {
    const token = s.token.toLowerCase();
    const acc = byToken.get(token) ?? { token, quantity: 0n, totalCost: 0n };
    acc.quantity += BigInt(s.quantity);
    acc.totalCost += BigInt(s.totalPaid);
    byToken.set(token, acc);
  }

  return finalizeHoldings([...byToken.values()]);
}

