import "server-only";
import { neon } from "@neondatabase/serverless";

/**
 * Dormant Neon (serverless Postgres) connection helper — reserved for genuinely **off-chain-only**
 * data (KYC PII, uploaded KP/title documents — only their hashes go on-chain — sessions,
 * notification prefs). None of that exists in R1, so nothing imports this yet.
 *
 * On-chain state is **never** mirrored here: the chain is the single source of truth, read live via
 * RPC (ADR-0009, superseding the ADR-0008 read-model write path). Keeping this thin helper (and the
 * `@neondatabase/serverless` dependency) means wiring the first off-chain table is an additive
 * change, not a re-add of the whole layer.
 */
export function getNeonClient(): ReturnType<typeof neon> {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error("DATABASE_URL is not set (reserved for future off-chain-only data).");
  }
  return neon(url);
}

