import "server-only";
import { type Address, type Hex, createPublicClient, http } from "viem";
import { getChain } from "@/lib/chains";
import { parseFromBlock } from "@/lib/fromBlock";
import { getOfferingAddress, primaryOfferingAbi } from "@/lib/offering/config";
import { aggregateHoldings, type Holding } from "@/lib/portfolio/holdings";
import { RPC_URL } from "@/lib/rpcUrls";

/**
 * Chain-only read of a Subscriber's portfolio (FR4.6). The on-chain `Subscribed` events are the
 * single source of truth (ADR-0009) — there is no DB mirror. We scan the configured
 * {PrimaryOffering} for the investor's `Subscribed` logs, resolve each offering's token via
 * `getOffering()`, then aggregate holdings + cost basis the same way the old read-model did.
 *
 * The pure decode/aggregate helpers are split out from the RPC call so they're unit-testable from
 * synthetic logs without mocking a client.
 */

/** A decoded `Subscribed` event with the provenance fields the history view needs. */
export interface DecodedSubscribed {
  offeringId: bigint;
  investor: Address;
  quantity: bigint;
  netToVendor: bigint;
  fee: bigint;
  totalPaid: bigint;
  txHash: Hex;
  blockNumber: bigint;
  logIndex: number;
}

/** One settlement in the history list (chain-derived; no off-chain id/timestamp). */
export interface SettlementEvent {
  /** ERC-3643 Fraction Token series address (resolved from the offering). */
  token: string;
  quantity: string;
  netToVendor: string;
  fee: string;
  totalPaid: string;
  txHash: string;
  blockNumber: string;
}

export interface PortfolioReadResult {
  holdings: Holding[];
  settlements: SettlementEvent[];
}

/** The structurally-typed shape of a decoded `Subscribed` log (from `getLogs`/`parseEventLogs`). */
interface DecodableSubscribedLog {
  args: {
    offeringId?: bigint;
    investor?: Address;
    quantity?: bigint;
    netToVendor?: bigint;
    fee?: bigint;
    totalPaid?: bigint;
  };
  transactionHash: Hex | null;
  blockNumber: bigint | null;
  logIndex: number | null;
}

/**
 * Map decoded `Subscribed` logs to {@link DecodedSubscribed}, dropping any log that isn't fully
 * decoded or is still pending (null block/tx/index) — a partial log can't be safely aggregated.
 */
export function decodeSubscribedLogs(logs: readonly DecodableSubscribedLog[]): DecodedSubscribed[] {
  const decoded: DecodedSubscribed[] = [];
  for (const log of logs) {
    const a = log.args;
    if (
      a.offeringId === undefined ||
      a.investor === undefined ||
      a.quantity === undefined ||
      a.netToVendor === undefined ||
      a.fee === undefined ||
      a.totalPaid === undefined ||
      log.transactionHash === null ||
      log.blockNumber === null ||
      log.logIndex === null
    ) {
      continue;
    }
    decoded.push({
      offeringId: a.offeringId,
      investor: a.investor,
      quantity: a.quantity,
      netToVendor: a.netToVendor,
      fee: a.fee,
      totalPaid: a.totalPaid,
      txHash: log.transactionHash,
      blockNumber: log.blockNumber,
      logIndex: log.logIndex,
    });
  }
  return decoded;
}

/**
 * Aggregate decoded `Subscribed` events into holdings (per token, with cost basis) and a
 * newest-first settlement history. `tokenByOffering` maps an offeringId to its Fraction Token
 * address (read from `getOffering()`); events for an unknown offering are skipped.
 */
export function aggregatePortfolio(
  events: readonly DecodedSubscribed[],
  tokenByOffering: ReadonlyMap<string, string>,
): PortfolioReadResult {
  const positions = events.flatMap((e) => {
    const token = tokenByOffering.get(e.offeringId.toString());
    return token
      ? [{ ...e, token, quantity: e.quantity.toString(), totalPaid: e.totalPaid.toString() }]
      : [];
  });

  const holdings = aggregateHoldings(positions);

  // Newest first: descending block, then logIndex within a block for a stable, deterministic order.
  const ordered = [...events].sort((a, b) => {
    if (a.blockNumber !== b.blockNumber) return a.blockNumber > b.blockNumber ? -1 : 1;
    return b.logIndex - a.logIndex;
  });
  const settlements: SettlementEvent[] = ordered.flatMap((e) => {
    const token = tokenByOffering.get(e.offeringId.toString());
    return token
      ? [
          {
            token,
            quantity: e.quantity.toString(),
            netToVendor: e.netToVendor.toString(),
            fee: e.fee.toString(),
            totalPaid: e.totalPaid.toString(),
            txHash: e.txHash,
            blockNumber: e.blockNumber.toString(),
          },
        ]
      : [];
  });

  return { holdings, settlements };
}

/** Thrown when the offering isn't configured for the requested chain (route → 501). */
export class PortfolioNotConfiguredError extends Error {}

/**
 * Read the connected wallet's portfolio straight from the chain. Filters `Subscribed` by the
 * indexed `investor` topic server-side, so the RPC returns only this wallet's settlements.
 */
export async function readPortfolio(params: {
  chainId: number;
  investor: Address;
}): Promise<PortfolioReadResult> {
  const offering = getOfferingAddress(params.chainId);
  if (!offering) {
    throw new PortfolioNotConfiguredError(
      `No primary offering configured for chain ${params.chainId}.`,
    );
  }
  const chain = getChain(params.chainId);
  if (!chain) {
    throw new PortfolioNotConfiguredError(`Unsupported chain ${params.chainId}.`);
  }

  const client = createPublicClient({ chain, transport: http(RPC_URL[params.chainId]) });

  const logs = await client.getContractEvents({
    abi: primaryOfferingAbi,
    address: offering,
    eventName: "Subscribed",
    args: { investor: params.investor },
    fromBlock: parseFromBlock(process.env.NEXT_PUBLIC_OFFERING_DEPLOY_BLOCK),
    toBlock: "latest",
  });
  const events = decodeSubscribedLogs(logs);

  // Resolve the Fraction Token per distinct offeringId (the event doesn't carry it). R1 typically
  // has one offering, so this is a tiny fan-out; getOffering reverts for an unknown id, so skip it.
  const offeringIds = [...new Set(events.map((e) => e.offeringId))];
  const tokenByOffering = new Map<string, string>();
  await Promise.all(
    offeringIds.map(async (id) => {
      try {
        const result = await client.readContract({
          address: offering,
          abi: primaryOfferingAbi,
          functionName: "getOffering",
          args: [id],
        });
        tokenByOffering.set(id.toString(), result.token);
      } catch {
        // Unknown/closed offering — leave it unresolved so its events are skipped.
      }
    }),
  );

  return aggregatePortfolio(events, tokenByOffering);
}

