import { describe, expect, it } from "vitest";
import {
  type Address,
  type Log,
  encodeAbiParameters,
  encodeEventTopics,
  parseEventLogs,
} from "viem";
import { primaryOfferingAbi } from "@/lib/offering/config";
import { aggregatePortfolio, decodeSubscribedLogs } from "@/lib/portfolio/onchain";

const OFFERING: Address = "0x1111111111111111111111111111111111111111";
const INVESTOR: Address = "0x2222222222222222222222222222222222222222";
const TOKEN_A: Address = "0xAAaAAA0000000000000000000000000000000001";
const TOKEN_B: Address = "0xBbBBbB0000000000000000000000000000000002";

const fields = {
  blockHash: "0x".padEnd(66, "a") as `0x${string}`,
  transactionHash: "0x".padEnd(66, "b") as `0x${string}`,
  transactionIndex: 0,
  removed: false,
};

/** Build a raw `Subscribed` log the way the chain would emit it. */
function subscribedLog(args: {
  offeringId: bigint;
  investor: Address;
  quantity: bigint;
  netToVendor: bigint;
  fee: bigint;
  totalPaid: bigint;
  blockNumber: bigint;
  logIndex: number;
}): Log {
  const topics = encodeEventTopics({
    abi: primaryOfferingAbi,
    eventName: "Subscribed",
    args: { offeringId: args.offeringId, investor: args.investor },
  });
  const data = encodeAbiParameters(
    [{ type: "uint256" }, { type: "uint256" }, { type: "uint256" }, { type: "uint256" }],
    [args.quantity, args.netToVendor, args.fee, args.totalPaid],
  );
  return {
    ...fields,
    address: OFFERING,
    topics,
    data,
    blockNumber: args.blockNumber,
    logIndex: args.logIndex,
  } as unknown as Log;
}

/** Decode synthetic raw logs the same way the chain read does (parseEventLogs → decodeSubscribedLogs). */
function decode(logs: Log[]) {
  const parsed = parseEventLogs({ abi: primaryOfferingAbi, eventName: "Subscribed", logs });
  return decodeSubscribedLogs(parsed);
}

describe("decodeSubscribedLogs", () => {
  it("decodes the on-chain amounts and provenance from synthetic logs", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 10n,
        netToVendor: 1000n,
        fee: 5n,
        totalPaid: 1005n,
        blockNumber: 7n,
        logIndex: 2,
      }),
    ]);

    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({
      offeringId: 0n,
      quantity: 10n,
      netToVendor: 1000n,
      fee: 5n,
      totalPaid: 1005n,
      blockNumber: 7n,
      logIndex: 2,
    });
    expect(events[0]!.investor.toLowerCase()).toBe(INVESTOR.toLowerCase());
  });
});

describe("aggregatePortfolio", () => {
  const tokenByOffering = new Map<string, string>([
    ["0", TOKEN_A],
    ["1", TOKEN_B],
  ]);

  it("aggregates holdings + cost basis from synthetic Subscribed logs", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 10n,
        netToVendor: 1000000000n,
        fee: 0n,
        totalPaid: 1000000000n,
        blockNumber: 1n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 5n,
        netToVendor: 450000000n,
        fee: 0n,
        totalPaid: 450000000n,
        blockNumber: 2n,
        logIndex: 0,
      }),
    ]);

    const { holdings } = aggregatePortfolio(events, tokenByOffering);

    expect(holdings).toHaveLength(1);
    expect(holdings[0]).toMatchObject({
      token: TOKEN_A.toLowerCase(),
      quantity: "15",
      totalCost: "1450000000",
      avgUnitCost: "96666666", // floor(1450000000 / 15)
    });
  });

  it("keeps distinct offerings' tokens separate and orders holdings by cost desc", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 100n,
        fee: 0n,
        totalPaid: 100n,
        blockNumber: 1n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 1n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 900n,
        fee: 0n,
        totalPaid: 900n,
        blockNumber: 1n,
        logIndex: 1,
      }),
    ]);

    const { holdings } = aggregatePortfolio(events, tokenByOffering);
    expect(holdings.map((h) => h.token)).toEqual([TOKEN_B.toLowerCase(), TOKEN_A.toLowerCase()]);
  });

  it("returns settlement history newest first (block desc, then logIndex desc)", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 10n,
        fee: 0n,
        totalPaid: 10n,
        blockNumber: 1n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 2n,
        netToVendor: 20n,
        fee: 0n,
        totalPaid: 20n,
        blockNumber: 3n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 3n,
        netToVendor: 30n,
        fee: 0n,
        totalPaid: 30n,
        blockNumber: 3n,
        logIndex: 1,
      }),
    ]);

    const { settlements } = aggregatePortfolio(events, tokenByOffering);
    expect(settlements.map((s) => s.quantity)).toEqual(["3", "2", "1"]);
    expect(settlements[0]).toMatchObject({ blockNumber: "3", token: TOKEN_A.toLowerCase() });
  });

  it("skips events whose offering token can't be resolved", () => {
    const events = decode([
      subscribedLog({
        offeringId: 99n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 10n,
        fee: 0n,
        totalPaid: 10n,
        blockNumber: 1n,
        logIndex: 0,
      }),
    ]);

    const result = aggregatePortfolio(events, tokenByOffering);
    expect(result.holdings).toEqual([]);
    expect(result.settlements).toEqual([]);
  });
});

