import { NextResponse } from "next/server";
import { isAddress } from "viem";
import { PortfolioNotConfiguredError, readPortfolio } from "@/lib/portfolio/onchain";

export const dynamic = "force-dynamic";

/**
 * Subscriber portfolio (issue #3, FR4.6), read **straight from the chain** — the on-chain
 * `Subscribed` events are the single source of truth (ADR-0009, superseding the ADR-0008 read-model
 * write path). This route keeps the RPC endpoint server-side and returns holdings (with cost basis)
 * plus settlement history for the given investor + chain. There is no write path: after a
 * `subscribe()` confirms, the UI re-reads here.
 */
export async function GET(request: Request) {
  // Intentionally public and unauthenticated in R1: everything returned is derived solely from
  // public on-chain events, so it exposes nothing that isn't already on-chain. `investor` is
  // required so this stays a per-wallet lookup, not an enumeration of every subscriber.
  const { searchParams } = new URL(request.url);
  const investor = searchParams.get("investor");
  if (!investor || !isAddress(investor)) {
    return NextResponse.json({ error: "Missing or invalid `investor` address" }, { status: 400 });
  }

  // Scope to a chain so positions from different networks don't mix into one holdings view.
  const chainIdRaw = searchParams.get("chainId");
  const chainId = chainIdRaw === null ? NaN : Number(chainIdRaw);
  if (!Number.isSafeInteger(chainId) || chainId <= 0) {
    return NextResponse.json({ error: "Missing or invalid `chainId`" }, { status: 400 });
  }

  try {
    const { holdings, settlements } = await readPortfolio({ chainId, investor });
    return NextResponse.json({ holdings, settlements });
  } catch (err) {
    if (err instanceof PortfolioNotConfiguredError) {
      return NextResponse.json({ error: err.message }, { status: 501 });
    }
    const message = err instanceof Error ? err.message : "Failed to read portfolio from chain";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

