import { NextResponse } from "next/server";
import { type Address, type Hex, isAddress } from "viem";
import { getSettlementsRepository } from "@/lib/db";
import {
  SettlementNotConfiguredError,
  SettlementVerificationError,
  verifySettlement,
  type SettlementClaim,
} from "@/lib/portfolio/verify";
import { blockedReadModelWrite } from "@/lib/writeGuard";

export const dynamic = "force-dynamic";

/** 0x-prefixed 32-byte transaction hash. */
const TX_HASH = /^0x[0-9a-fA-F]{64}$/;

/**
 * Primary-subscription settlement read-model (issue #3, FR4.6). GET returns a wallet's
 * settlement history and derived holdings (cost basis); POST records a confirmed DvP
 * subscription so the portfolio reflects it. The on-chain {Subscribed} event is the source of
 * truth; this is the off-chain projection used by the UI (and the Ctrl Alt reconciliation seam,
 * FR4.9 / issue #12).
 */
export async function GET(request: Request) {
  // Intentionally public and unauthenticated in R1: the read-model is derived solely from public
  // on-chain Subscribed events, so it exposes nothing that isn't already on-chain. If this ever
  // grows to hold off-chain/PII data, add an auth boundary (e.g. SIWE) and enforce
  // investor == authenticated address. Still require `investor` here so it stays a per-wallet
  // lookup, not an enumeration of every subscriber.
  const { searchParams } = new URL(request.url);
  const investor = searchParams.get("investor");
  if (!investor || !isAddress(investor)) {
    return NextResponse.json({ error: "Missing or invalid `investor` address" }, { status: 400 });
  }

  // Scope to a chain so positions from different networks don't mix into one holdings view.
  let chainId: number | undefined;
  const chainIdRaw = searchParams.get("chainId");
  if (chainIdRaw !== null) {
    const parsed = Number(chainIdRaw);
    if (!Number.isSafeInteger(parsed) || parsed <= 0) {
      return NextResponse.json({ error: "Invalid `chainId`" }, { status: 400 });
    }
    chainId = parsed;
  }

  const repo = getSettlementsRepository();
  // Holdings aggregate the wallet's *entire* chain-scoped history (DB-side), so totals stay
  // correct regardless of size; the history list is a bounded newest-first page for display.
  const [holdings, settlements] = await Promise.all([
    repo.sumHoldings({ investor, chainId }),
    repo.list({ investor, chainId }),
  ]);
  return NextResponse.json({ settlements, holdings });
}

/**
 * The client only needs to identify the on-chain settlement; the route re-derives the persisted
 * amounts from the `Subscribed` event itself, so any client-supplied amounts are ignored.
 */
function parseClaim(body: unknown): SettlementClaim | null {
  if (typeof body !== "object" || body === null) return null;
  const b = body as Record<string, unknown>;
  if (
    typeof b.chainId !== "number" ||
    !Number.isSafeInteger(b.chainId) ||
    b.chainId <= 0 ||
    typeof b.offeringId !== "number" ||
    !Number.isSafeInteger(b.offeringId) ||
    b.offeringId < 0 ||
    typeof b.investor !== "string" ||
    !isAddress(b.investor) ||
    typeof b.txHash !== "string" ||
    !TX_HASH.test(b.txHash)
  ) {
    return null;
  }
  return {
    chainId: b.chainId,
    offeringId: b.offeringId,
    investor: b.investor as Address,
    txHash: b.txHash as Hex,
  };
}

export async function POST(request: Request) {
  const blocked = blockedReadModelWrite();
  if (blocked) return blocked;

  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const claim = parseClaim(json);
  if (!claim) {
    return NextResponse.json({ error: "Invalid settlement payload" }, { status: 400 });
  }

  let record: Awaited<ReturnType<typeof verifySettlement>>;
  try {
    // Persist only what the chain confirms — never the client's claimed amounts.
    record = await verifySettlement(claim);
  } catch (err) {
    if (err instanceof SettlementNotConfiguredError) {
      return NextResponse.json({ error: err.message }, { status: 501 });
    }
    if (err instanceof SettlementVerificationError) {
      return NextResponse.json({ error: err.message }, { status: 422 });
    }
    const message = err instanceof Error ? err.message : "Settlement verification failed";
    return NextResponse.json({ error: message }, { status: 500 });
  }

  const repo = getSettlementsRepository();
  // add() is idempotent on (chainId, txHash): a retried POST returns the existing row rather than
  // creating a new one, so respond 200 (the handler can't distinguish created vs existing).
  const saved = await repo.add(record);
  return NextResponse.json({ settlement: saved }, { status: 200 });
}

