import type { Hex } from "viem";
import { getRecordsRepository } from "@/lib/db";
import {
  type NoteClaim,
  RecordNotConfiguredError,
  RecordVerificationError,
  verifyNoteUpdate,
} from "@/lib/records/verify";
import { blockedReadModelWrite } from "@/lib/writeGuard";

export const dynamic = "force-dynamic";

/** 0x-prefixed 32-byte transaction hash. */
const TX_HASH = /^0x[0-9a-fA-F]{64}$/;

export async function GET() {
  const repo = getRecordsRepository();
  const records = await repo.list();
  return NextResponse.json({ records });
}

/**
 * The client only identifies the on-chain note update; the route re-derives note + updatedBy
 * from the `NoteUpdated` event, so client-supplied values are ignored (no forged/spam rows).
 */
function parseClaim(body: unknown): NoteClaim | null {
  if (typeof body !== "object" || body === null) return null;
  const b = body as Record<string, unknown>;
  if (
    typeof b.chainId !== "number" ||
    !Number.isSafeInteger(b.chainId) ||
    b.chainId <= 0 ||
    typeof b.txHash !== "string" ||
    !TX_HASH.test(b.txHash)
  ) {
    return null;
  }
  return { chainId: b.chainId, txHash: b.txHash as Hex };
}

export async function POST(request: Request) {
  const blocked = blockedReadModelWrite();
  if (blocked) return blocked;

  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const claim = parseClaim(json);
  if (!claim) {
    return NextResponse.json({ error: "Invalid record payload" }, { status: 400 });
  }

  let record: Awaited<ReturnType<typeof verifyNoteUpdate>>;
  try {
    // Persist only what the chain confirms — never the client's claimed note/updatedBy.
    record = await verifyNoteUpdate(claim);
  } catch (err) {
    if (err instanceof RecordNotConfiguredError) {
      return NextResponse.json({ error: err.message }, { status: 501 });
    }
    if (err instanceof RecordVerificationError) {
      return NextResponse.json({ error: err.message }, { status: 422 });
    }
    const message = err instanceof Error ? err.message : "Record verification failed";
    return NextResponse.json({ error: message }, { status: 500 });
  }

  const repo = getRecordsRepository();
  // add() is idempotent on (chainId, txHash): a retried POST returns the existing row rather than
  // creating a new one, so respond 200 (the handler can't distinguish created vs existing).
  const saved = await repo.add(record);
  return NextResponse.json({ record: saved }, { status: 200 });
}

