import { useCallback, useEffect, useState } from "react";
import { formatUnits } from "viem";
import { useAccount, useReadContract } from "wagmi";
import { erc20Abi, getOfferingAddress, primaryOfferingAbi } from "@/lib/offering/config";
import type { Holding } from "@/lib/portfolio/holdings";
import type { SettlementEvent } from "@/lib/portfolio/onchain";

/**
 * Subscriber portfolio (issue #3, FR4.6): holdings with cost basis and settlement history for
 * the connected wallet, read **straight from the chain** via /api/portfolio (the on-chain
 * `Subscribed` events are the source of truth — ADR-0009; no DB mirror). Listens for the
 * `roughnet:settlement` event the subscription flow dispatches so it re-reads right after a DvP
 * settles.
 */
export function Portfolio() {
  const { address, chainId, isConnected } = useAccount();
  const [holdings, setHoldings] = useState<Holding[]>([]);
  const [settlements, setSettlements] = useState<SettlementEvent[]>([]);

  // Derive the stablecoin's decimals/symbol from the offering's paymentToken() on-chain so amounts
  // stay correct if a production stablecoin (issue #12) with different decimals/symbol is swapped in.
  const offeringAddress = chainId ? getOfferingAddress(chainId) : undefined;
  const stablecoinRead = useReadContract({
    abi: primaryOfferingAbi,
    address: offeringAddress,
    functionName: "paymentToken",
    query: { enabled: Boolean(offeringAddress) },
  });
  // Gate on offeringAddress so a stale token from the previous chain doesn't drive decimals/symbol
  // after a chain switch (wagmi retains a disabled query's last data).
  const stablecoin = offeringAddress ? stablecoinRead.data : undefined;
  const decimalsRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "decimals",
    query: { enabled: Boolean(stablecoin) },
  });
  const symbolRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "symbol",
    query: { enabled: Boolean(stablecoin) },
  });
  const decimals = Number(decimalsRead.data ?? 6);
  const symbol = symbolRead.data ?? "mUSD";

  const load = useCallback(async () => {
    if (!address) {
      setHoldings([]);
      setSettlements([]);
      return;
    }
    // Scope the portfolio to the connected chain so multi-chain activity isn't mixed together.
    // The chain read needs a chainId, so skip until the wallet reports one.
    if (!chainId) {
      setHoldings([]);
      setSettlements([]);
      return;
    }
    const params = new URLSearchParams({ investor: address, chainId: String(chainId) });
    const res = await fetch(`/api/portfolio?${params.toString()}`);
    if (res.ok) {
      const json = (await res.json()) as { holdings: Holding[]; settlements: SettlementEvent[] };
      setHoldings(json.holdings);
      setSettlements(json.settlements);
    }
  }, [address, chainId]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    const handler = () => void load();
    window.addEventListener("roughnet:settlement", handler);
    return () => window.removeEventListener("roughnet:settlement", handler);
  }, [load]);

  const usd = (v: string) => formatUnits(BigInt(v), decimals);
  const short = (a: string) => `${a.slice(0, 6)}…${a.slice(-4)}`;

  return (
    <section className="panel">
      <h2 style={{ margin: 0 }}>Your portfolio</h2>

      {!isConnected ? (
        <p className="muted">Connect your wallet to see holdings and settlement history.</p>
      ) : (
        <>
          <h3>Holdings &amp; cost basis</h3>
          {holdings.length === 0 ? (
            <p className="muted">No holdings yet — subscribe to a primary offering above.</p>
          ) : (
            <ul className="records">
              {holdings.map((h) => (
                <li key={h.token}>
                  <code>{short(h.token)}</code> · <strong>{h.quantity}</strong> fractions · cost{" "}
                  {usd(h.totalCost)} {symbol} · basis {usd(h.avgUnitCost)} {symbol}/fraction
                </li>
              ))}
            </ul>
          )}

          <h3>Settlement history</h3>
          {settlements.length === 0 ? (
            <p className="muted">No settlements yet.</p>
          ) : (
            <ul className="records">
              {settlements.map((s) => (
                <li key={s.id}>
                  Bought <strong>{s.quantity}</strong> of <code>{short(s.token)}</code> for{" "}
                  {usd(s.totalPaid)} {symbol} · <code>{s.txHash.slice(0, 10)}…</code> ·{" "}
                  <span className="muted">{new Date(s.createdAt).toLocaleString()}</span>
                </li>
              ))}
            </ul>
          )}
        </>
      )}
    </section>
  );
}

