// Once the DvP tx confirms, ask the server to record it. The server re-derives the settlement
// from the on-chain Subscribed event, so the client only sends the claim (chain, offering,
// investor, txHash). Only refresh + signal the portfolio when persistence actually succeeds.
useEffect(() => {
  if (!subscribeReceipt.isSuccess || !subscribe.data || !submitted) return;
  const ctx = submitted;
  const txHash = subscribe.data;
  // The API takes offeringId as a JS number; guard the bigint->number cast so a huge id can't
  // silently lose precision and record the wrong offering.
  if (ctx.offeringId > BigInt(Number.MAX_SAFE_INTEGER)) {
    setPersistError("Offering id is too large to record.");
    return;
  }
  void (async () => {
    setPersistError(null);
    try {
      const res = await fetch("/api/portfolio", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          chainId: ctx.chainId,
          offeringId: Number(ctx.offeringId),
          investor: ctx.investor,
          txHash,
        }),
      });
      if (!res.ok) {
        const json = (await res.json().catch(() => ({}))) as { error?: string };
        setPersistError(json.error ?? `Failed to record settlement (${res.status}).`);
        return;
      }
      await Promise.all([balanceRead.refetch(), allowanceRead.refetch(), offeringRead.refetch()]);
      window.dispatchEvent(new CustomEvent("roughnet:settlement"));
    } catch (err) {
      setPersistError(err instanceof Error ? err.message : "Failed to record settlement.");
    }
  })();
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [subscribeReceipt.isSuccess]);

