import { describe, expect, it } from "vitest";
import {
  type Address,
  type Log,
  encodeAbiParameters,
  encodeEventTopics,
  parseEventLogs,
} from "viem";
import { primaryOfferingAbi } from "@/lib/offering/config";
import { aggregatePortfolio, decodeSubscribedLogs } from "@/lib/portfolio/onchain";

const OFFERING: Address = "0x1111111111111111111111111111111111111111";
const INVESTOR: Address = "0x2222222222222222222222222222222222222222";
const TOKEN_A: Address = "0xAAaAAA0000000000000000000000000000000001";
const TOKEN_B: Address = "0xBbBBbB0000000000000000000000000000000002";

const fields = {
  blockHash: "0x".padEnd(66, "a") as `0x${string}`,
  transactionHash: "0x".padEnd(66, "b") as `0x${string}`,
  transactionIndex: 0,
  removed: false,
};

/** Build a raw `Subscribed` log the way the chain would emit it. */
function subscribedLog(args: {
  offeringId: bigint;
  investor: Address;
  quantity: bigint;
  netToVendor: bigint;
  fee: bigint;
  totalPaid: bigint;
  blockNumber: bigint;
  logIndex: number;
}): Log {
  const topics = encodeEventTopics({
    abi: primaryOfferingAbi,
    eventName: "Subscribed",
    args: { offeringId: args.offeringId, investor: args.investor },
  });
  const data = encodeAbiParameters(
    [{ type: "uint256" }, { type: "uint256" }, { type: "uint256" }, { type: "uint256" }],
    [args.quantity, args.netToVendor, args.fee, args.totalPaid],
  );
  return {
    ...fields,
    address: OFFERING,
    topics,
    data,
    blockNumber: args.blockNumber,
    logIndex: args.logIndex,
  } as unknown as Log;
}

/** Decode synthetic raw logs the same way the chain read does (parseEventLogs → decodeSubscribedLogs). */
function decode(logs: Log[]) {
  const parsed = parseEventLogs({ abi: primaryOfferingAbi, eventName: "Subscribed", logs });
  return decodeSubscribedLogs(parsed);
}

describe("decodeSubscribedLogs", () => {
  it("decodes the on-chain amounts and provenance from synthetic logs", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 10n,
        netToVendor: 1000n,
        fee: 5n,
        totalPaid: 1005n,
        blockNumber: 7n,
        logIndex: 2,
      }),
    ]);

    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({
      offeringId: 0n,
      quantity: 10n,
      netToVendor: 1000n,
      fee: 5n,
      totalPaid: 1005n,
      blockNumber: 7n,
      logIndex: 2,
    });
    expect(events[0]!.investor.toLowerCase()).toBe(INVESTOR.toLowerCase());
  });
});

describe("aggregatePortfolio", () => {
  const tokenByOffering = new Map<string, string>([
    ["0", TOKEN_A],
    ["1", TOKEN_B],
  ]);

  it("aggregates holdings + cost basis from synthetic Subscribed logs", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 10n,
        netToVendor: 1000000000n,
        fee: 0n,
        totalPaid: 1000000000n,
        blockNumber: 1n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 5n,
        netToVendor: 450000000n,
        fee: 0n,
        totalPaid: 450000000n,
        blockNumber: 2n,
        logIndex: 0,
      }),
    ]);

    const { holdings } = aggregatePortfolio(events, tokenByOffering);

    expect(holdings).toHaveLength(1);
    expect(holdings[0]).toMatchObject({
      token: TOKEN_A.toLowerCase(),
      quantity: "15",
      totalCost: "1450000000",
      avgUnitCost: "96666666", // floor(1450000000 / 15)
    });
  });

  it("keeps distinct offerings' tokens separate and orders holdings by cost desc", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 100n,
        fee: 0n,
        totalPaid: 100n,
        blockNumber: 1n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 1n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 900n,
        fee: 0n,
        totalPaid: 900n,
        blockNumber: 1n,
        logIndex: 1,
      }),
    ]);

    const { holdings } = aggregatePortfolio(events, tokenByOffering);
    expect(holdings.map((h) => h.token)).toEqual([TOKEN_B.toLowerCase(), TOKEN_A.toLowerCase()]);
  });

  it("returns settlement history newest first (block desc, then logIndex desc)", () => {
    const events = decode([
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 10n,
        fee: 0n,
        totalPaid: 10n,
        blockNumber: 1n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 2n,
        netToVendor: 20n,
        fee: 0n,
        totalPaid: 20n,
        blockNumber: 3n,
        logIndex: 0,
      }),
      subscribedLog({
        offeringId: 0n,
        investor: INVESTOR,
        quantity: 3n,
        netToVendor: 30n,
        fee: 0n,
        totalPaid: 30n,
        blockNumber: 3n,
        logIndex: 1,
      }),
    ]);

    const { settlements } = aggregatePortfolio(events, tokenByOffering);
    expect(settlements.map((s) => s.quantity)).toEqual(["3", "2", "1"]);
    expect(settlements[0]).toMatchObject({ blockNumber: "3", token: TOKEN_A.toLowerCase() });
  });

  it("skips events whose offering token can't be resolved", () => {
    const events = decode([
      subscribedLog({
        offeringId: 99n,
        investor: INVESTOR,
        quantity: 1n,
        netToVendor: 10n,
        fee: 0n,
        totalPaid: 10n,
        blockNumber: 1n,
        logIndex: 0,
      }),
    ]);

    const result = aggregatePortfolio(events, tokenByOffering);
    expect(result.holdings).toEqual([]);
    expect(result.settlements).toEqual([]);
  });
});

"use client";

import { useCallback, useEffect, useState } from "react";
import { formatUnits } from "viem";
import { useAccount, useReadContract } from "wagmi";
import { erc20Abi, getOfferingAddress, primaryOfferingAbi } from "@/lib/offering/config";
import type { Holding } from "@/lib/portfolio/holdings";
import type { SettlementEvent } from "@/lib/portfolio/onchain";

/**
 * Subscriber portfolio (issue #3, FR4.6): holdings with cost basis and settlement history for
 * the connected wallet, read **straight from the chain** via /api/portfolio (the on-chain
 * `Subscribed` events are the source of truth — ADR-0009; no DB mirror). Listens for the
 * `roughnet:settlement` event the subscription flow dispatches so it re-reads right after a DvP
 * settles.
 */
export function Portfolio() {
  const { address, chainId, isConnected } = useAccount();
  const [holdings, setHoldings] = useState<Holding[]>([]);
  const [settlements, setSettlements] = useState<SettlementEvent[]>([]);

  // Derive the stablecoin's decimals/symbol from the offering's paymentToken() on-chain so amounts
  // stay correct if a production stablecoin (issue #12) with different decimals/symbol is swapped in.
  const offeringAddress = chainId ? getOfferingAddress(chainId) : undefined;
  const stablecoinRead = useReadContract({
    abi: primaryOfferingAbi,
    address: offeringAddress,
    functionName: "paymentToken",
    query: { enabled: Boolean(offeringAddress) },
  });
  // Gate on offeringAddress so a stale token from the previous chain doesn't drive decimals/symbol
  // after a chain switch (wagmi retains a disabled query's last data).
  const stablecoin = offeringAddress ? stablecoinRead.data : undefined;
  const decimalsRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "decimals",
    query: { enabled: Boolean(stablecoin) },
  });
  const symbolRead = useReadContract({
    abi: erc20Abi,
    address: stablecoin,
    functionName: "symbol",
    query: { enabled: Boolean(stablecoin) },
  });
  const decimals = Number(decimalsRead.data ?? 6);
  const symbol = symbolRead.data ?? "mUSD";

  const load = useCallback(async () => {
    if (!address) {
      setHoldings([]);
      setSettlements([]);
      return;
    }
    // Scope the portfolio to the connected chain so multi-chain activity isn't mixed together.
    // The chain read needs a chainId, so skip until the wallet reports one.
    if (!chainId) {
      setHoldings([]);
      setSettlements([]);
      return;
    }
    const params = new URLSearchParams({ investor: address, chainId: String(chainId) });
    const res = await fetch(`/api/portfolio?${params.toString()}`);
    if (res.ok) {
      const json = (await res.json()) as { holdings: Holding[]; settlements: SettlementEvent[] };
      setHoldings(json.holdings);
      setSettlements(json.settlements);
    }
  }, [address, chainId]);

  useEffect(() => {
    void load();
  }, [load]);

  useEffect(() => {
    const handler = () => void load();
    window.addEventListener("roughnet:settlement", handler);
    return () => window.removeEventListener("roughnet:settlement", handler);
  }, [load]);

  const usd = (v: string) => formatUnits(BigInt(v), decimals);
  const short = (a: string) => `${a.slice(0, 6)}…${a.slice(-4)}`;

  return (
    <section className="panel">
      <h2 style={{ margin: 0 }}>Your portfolio</h2>

      {!isConnected ? (
        <p className="muted">Connect your wallet to see holdings and settlement history.</p>
      ) : (
        <>
          <h3>Holdings &amp; cost basis</h3>
          {holdings.length === 0 ? (
            <p className="muted">No holdings yet — subscribe to a primary offering above.</p>
          ) : (
            <ul className="records">
              {holdings.map((h) => (
                <li key={h.token}>
                  <code>{short(h.token)}</code> · <strong>{h.quantity}</strong> fractions · cost{" "}
                  {usd(h.totalCost)} {symbol} · basis {usd(h.avgUnitCost)} {symbol}/fraction
                </li>
              ))}
            </ul>
          )}

          <h3>Settlement history</h3>
          {settlements.length === 0 ? (
            <p className="muted">No settlements yet.</p>
          ) : (
            <ul className="records">
              {settlements.map((s) => (
                <li key={s.txHash}>
                  Bought <strong>{s.quantity}</strong> of <code>{short(s.token)}</code> for{" "}
                  {usd(s.totalPaid)} {symbol} · <code>{s.txHash.slice(0, 10)}…</code> ·{" "}
                  <span className="muted">block {s.blockNumber}</span>
                </li>
              ))}
            </ul>
          )}
        </>
      )}
    </section>
  );
}

