+import type { BlockNumber, BlockTag } from "viem";
+
+/**
+ * The `fromBlock` to start a `getContractEvents` scan from. A contract's deploy block keeps the scan
+ * tight; when unknown we fall back to `"earliest"`, which is fine on R1 testnets but can exceed an
+ * RPC provider's block-range limit on busy mainnets — the scale answer is an indexer (out of scope,
+ * see ADR-0009). Set e.g. `NEXT_PUBLIC_OFFERING_DEPLOY_BLOCK` to the deploy block to keep reads cheap.
+ */
+export function parseFromBlock(raw: string | undefined): BlockNumber | BlockTag {
+  if (!raw) return "earliest";
+  try {
+    const value = BigInt(raw);
+    return value >= 0n ? value : "earliest";
+  } catch {
+    return "earliest";
+  }
+}
