"use client";

import { ConnectButton } from "@rainbow-me/rainbowkit";
import { useCallback, useEffect, useState } from "react";
import { useAccount, useReadContract, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { getRegistryAddress, registryAbi } from "@/lib/contract";
import type { NoteRecord } from "@/lib/registry/onchain";

export function RegistryDemo() {
  const { chainId, isConnected } = useAccount();
  const registry = chainId ? getRegistryAddress(chainId) : undefined;

  const [draft, setDraft] = useState("");
  const [records, setRecords] = useState<NoteRecord[]>([]);

  const noteRead = useReadContract({
    abi: registryAbi,
    address: registry,
    functionName: "note",
    query: { enabled: Boolean(registry) },
  });

  const { writeContract, data: txHash, isPending, error: writeError } = useWriteContract();
  const receipt = useWaitForTransactionReceipt({ hash: txHash });

  // The Register history is read straight from the chain's `NoteUpdated` events (ADR-0009 — no DB
  // mirror); scope it to the connected chain so notes from other networks don't mix in.
  const loadRecords = useCallback(async () => {
    if (!chainId) {
      setRecords([]);
      return;
    }
    const res = await fetch(`/api/records?chainId=${chainId}`);
    if (res.ok) {
      const json = (await res.json()) as { records: NoteRecord[] };
      setRecords(json.records);
    }
  }, [chainId]);

  useEffect(() => {
    void loadRecords();
  }, [loadRecords]);

  // Once the setNote tx confirms, the chain already holds the new note + a fresh `NoteUpdated`
  // event — re-read both the live note and the history straight from chain (no DB write).
  useEffect(() => {
    if (!receipt.isSuccess) return;
    void noteRead.refetch();
    void loadRecords();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [receipt.isSuccess]);

  const onSubmit = () => {
    if (!registry || draft.length === 0 || !chainId) return;
    writeContract({ abi: registryAbi, address: registry, functionName: "setNote", args: [draft] });
  };

  return (
    <section className="panel">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2 style={{ margin: 0 }}>Update note (self-custodial wallet)</h2>
        <ConnectButton />
      </div>

      {!isConnected ? (
        <p className="muted">Connect MetaMask or WalletConnect to write.</p>
      ) : !registry ? (
        <p className="muted">No registry deployed on the connected chain (chainId {chainId}).</p>
      ) : (
        <>
          <p className="muted">
            Live note: <strong>{noteRead.data ?? "…"}</strong>
          </p>
          <div className="row">
            <input
              type="text"
              value={draft}
              placeholder="New note"
              onChange={(e) => setDraft(e.target.value)}
            />
            <button onClick={onSubmit} disabled={isPending || receipt.isLoading || draft.length === 0}>
              {isPending ? "Confirm in wallet…" : receipt.isLoading ? "Mining…" : "Set note"}
            </button>
          </div>
          {writeError ? <p className="muted">⚠ {writeError.message}</p> : null}
          {receipt.isSuccess ? (
            <p className="muted">✓ Confirmed on-chain.</p>
          ) : receipt.isLoading ? (
            <p className="muted">Mining…</p>
          ) : null}
        </>
      )}

      <h3>Note history (on-chain read-back)</h3>
      {records.length === 0 ? (
        <p className="muted">No records yet.</p>
      ) : (
        <ul className="records">
          {records.map((r) => (
            <li key={r.txHash}>
              <strong>{r.note}</strong> · by <code>{r.updatedBy.slice(0, 10)}…</code> ·{" "}
              <code>{r.txHash.slice(0, 10)}…</code> · <span className="muted">block {r.blockNumber}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

import "server-only";
import { type Address, createPublicClient, http } from "viem";
import { getChain } from "@/lib/chains";
import { parseFromBlock } from "@/lib/fromBlock";
import { getOfferingAddress, primaryOfferingAbi } from "@/lib/offering/config";
import { aggregatePortfolio, decodeSubscribedLogs, type PortfolioReadResult } from "./aggregate";
import { RPC_URL } from "@/lib/rpcUrls";

export type {
  DecodedSubscribed,
  PortfolioReadResult,
  SettlementEvent,
} from "./aggregate";

/**
 * Chain-only read of a Subscriber's portfolio (FR4.6). The on-chain `Subscribed` events are the
 * single source of truth (ADR-0009) — there is no DB mirror. We scan the configured
 * {PrimaryOffering} for the investor's `Subscribed` logs, resolve each offering's token via
 * `getOffering()`, then aggregate holdings + cost basis. The pure decode/aggregate lives in
 * `aggregate.ts` so it's unit-testable without a client.
 */

/** Thrown when the offering isn't configured for the requested chain (route → 501). */
export class PortfolioNotConfiguredError extends Error {}

/**
 * Read the connected wallet's portfolio straight from the chain. Filters `Subscribed` by the
 * indexed `investor` topic server-side, so the RPC returns only this wallet's settlements.
 */
export async function readPortfolio(params: {
  chainId: number;
  investor: Address;
}): Promise<PortfolioReadResult> {
  const offering = getOfferingAddress(params.chainId);
  if (!offering) {
    throw new PortfolioNotConfiguredError(
      `No primary offering configured for chain ${params.chainId}.`,
    );
  }
  const chain = getChain(params.chainId);
  if (!chain) {
    throw new PortfolioNotConfiguredError(`Unsupported chain ${params.chainId}.`);
  }

  const client = createPublicClient({ chain, transport: http(RPC_URL[params.chainId]) });

  const logs = await client.getContractEvents({
    abi: primaryOfferingAbi,
    address: offering,
    eventName: "Subscribed",
    args: { investor: params.investor },
    fromBlock: parseFromBlock(process.env.NEXT_PUBLIC_OFFERING_DEPLOY_BLOCK),
    toBlock: "latest",
  });
  const events = decodeSubscribedLogs(logs);

  // Resolve the Fraction Token per distinct offeringId (the event doesn't carry it). R1 typically
  // has one offering, so this is a tiny fan-out; getOffering reverts for an unknown id, so skip it.
  const offeringIds = [...new Set(events.map((e) => e.offeringId))];
  const tokenByOffering = new Map<string, string>();
  await Promise.all(
    offeringIds.map(async (id) => {
      try {
        const result = await client.readContract({
          address: offering,
          abi: primaryOfferingAbi,
          functionName: "getOffering",
          args: [id],
        });
        tokenByOffering.set(id.toString(), result.token);
      } catch {
        // Unknown/closed offering — leave it unresolved so its events are skipped.
      }
    }),
  );

  return aggregatePortfolio(events, tokenByOffering);
}

