import "server-only";
import { createPublicClient, http } from "viem";
import { getChain } from "@/lib/chains";
import { getRegistryAddress, registryAbi } from "@/lib/contract";
import { parseFromBlock } from "@/lib/fromBlock";
import { RPC_URL } from "@/lib/rpcUrls";

/**
 * Chain-only read of the public Register history (the Register read-model that ADR-0009 makes
 * DB-free). The on-chain `NoteUpdated` events are the single source of truth — no DB mirror. The
 * current note is still read via `note()` in `lib/serverReads.ts`; this adds the history list.
 */

/** One Register update, derived from a `NoteUpdated` event. */
export interface NoteRecord {
  note: string;
  updatedBy: string;
  /** Monotonic update counter from the contract (newest = highest). */
  count: string;
  txHash: string;
  blockNumber: string;
}

/** Thrown when no registry is configured for the requested chain (route → 501). */
export class RegistryNotConfiguredError extends Error {}

/**
 * Read the Register's note history for a chain, newest first. Scans `NoteUpdated` logs from the
 * registry; block-range limits are an indexer concern at scale (out of scope, ADR-0009).
 */
export async function readNoteHistory(chainId: number, limit = 50): Promise<NoteRecord[]> {
  const address = getRegistryAddress(chainId);
  if (!address) {
    throw new RegistryNotConfiguredError(`No registry configured for chain ${chainId}.`);
  }
