// already tracks the query's error state, so contain the rejection to avoid an unhandled-rejection
// warning (same for the faucet/subscribe refreshes below).
useEffect(() => {
  if (approveReceipt.isSuccess) void allowanceRead.refetch().catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [approveReceipt.isSuccess]);

// Refresh balance once the faucet confirms.
useEffect(() => {
  if (faucetReceipt.isSuccess) void balanceRead.refetch().catch(() => {});
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [faucetReceipt.isSuccess]);

// Once the DvP tx confirms, the chain is already the source of truth (no DB write — ADR-0009).
// Refresh the on-chain balance/allowance/offering and signal the portfolio to re-read from chain.
useEffect(() => {
  if (!subscribeReceipt.isSuccess) return;
  void Promise.all([
    balanceRead.refetch(),
    allowanceRead.refetch(),
    offeringRead.refetch(),
  ]).catch(() => {});
  window.dispatchEvent(new CustomEvent("roughnet:settlement"));
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [subscribeReceipt.isSuccess]);

