import type { Hex } from "viem";

/**
 * Pure decode/sort half of the chain-only Register history read (the RPC half lives in
 * `onchain.ts`, which is server-only). Kept separate so this logic is unit-testable from synthetic
 * `NoteUpdated` logs without mocking an RPC client — the same split as the portfolio
 * `aggregate.ts` / `onchain.ts` pair.
 */

/** One Register update, derived from a `NoteUpdated` event. */
export interface NoteRecord {
  note: string;
  updatedBy: string;
  /** Monotonic update counter from the contract (newest = highest). */
  count: string;
  txHash: string;
  blockNumber: string;
}

/** The structurally-typed shape of a decoded `NoteUpdated` log (from `getContractEvents`/`parseEventLogs`). */
export interface DecodableNoteUpdatedLog {
  args: {
    by?: string;
    note?: string;
    count?: bigint;
  };
  transactionHash: Hex | null;
  blockNumber: bigint | null;
}

/**
 * Decode `NoteUpdated` logs into newest-first {@link NoteRecord}s, dropping any log that isn't fully
 * decoded or is still pending (null tx/block) — a partial log would render misleading provenance.
 * Newest-first is by the contract's monotonic `count`; the comparator returns 0 on equality so it
 * obeys the total-order contract. Returns at most `limit` records.
 */
export function decodeNoteUpdatedLogs(
  logs: readonly DecodableNoteUpdatedLog[],
  limit = 50,
): NoteRecord[] {
  const records: NoteRecord[] = [];
  for (const log of logs) {
    const { note, by, count } = log.args;
    if (
      note === undefined ||
      by === undefined ||
      count === undefined ||
      log.transactionHash === null ||
      log.blockNumber === null
    ) {
      continue;
    }
    records.push({
      note,
      updatedBy: by,
      count: count.toString(),
      txHash: log.transactionHash,
      blockNumber: log.blockNumber.toString(),
    });
  }

  records.sort((a, b) => {
    const delta = BigInt(b.count) - BigInt(a.count);
    return delta > 0n ? 1 : delta < 0n ? -1 : 0;
  });
  return records.slice(0, limit);
}

