import { describe, expect, it } from "vitest";
import {
  type Address,
  type Log,
  encodeAbiParameters,
  encodeEventTopics,
  parseEventLogs,
} from "viem";
import { registryAbi } from "@/lib/contract";
import { decodeNoteUpdatedLogs } from "@/lib/registry/aggregate";

const BY: Address = "0x1111111111111111111111111111111111111111";

const fields = {
  blockHash: "0x".padEnd(66, "a") as `0x${string}`,
  transactionIndex: 0,
  logIndex: 0,
  removed: false,
};

/** Build a raw `NoteUpdated` log the way the chain would emit it. */
function noteUpdatedLog(args: {
  by: Address;
  note: string;
  count: bigint;
  txHash: `0x${string}`;
  blockNumber: bigint;
}): Log {
  const topics = encodeEventTopics({
    abi: registryAbi,
    eventName: "NoteUpdated",
    args: { by: args.by, count: args.count },
  });
  const data = encodeAbiParameters([{ type: "string" }], [args.note]);
  return {
    ...fields,
    address: BY,
    topics,
    data,
    transactionHash: args.txHash,
    blockNumber: args.blockNumber,
  } as unknown as Log;
}

/** Decode synthetic raw logs the same way the chain read does. */
function decode(logs: Log[], limit?: number) {
  const parsed = parseEventLogs({ abi: registryAbi, eventName: "NoteUpdated", logs });
  return decodeNoteUpdatedLogs(parsed, limit);
}

const txHash = (n: number) => `0x${n.toString().padStart(64, "0")}` as `0x${string}`;

describe("decodeNoteUpdatedLogs", () => {
  it("decodes note + provenance from synthetic logs", () => {
    const records = decode([
      noteUpdatedLog({ by: BY, note: "hello", count: 1n, txHash: txHash(1), blockNumber: 7n }),
    ]);

    expect(records).toHaveLength(1);
    expect(records[0]).toMatchObject({
      note: "hello",
      count: "1",
      blockNumber: "7",
      txHash: txHash(1),
    });
    expect(records[0]!.updatedBy.toLowerCase()).toBe(BY.toLowerCase());
  });

  it("orders newest first by the contract's monotonic count", () => {
    const records = decode([
      noteUpdatedLog({ by: BY, note: "first", count: 1n, txHash: txHash(1), blockNumber: 1n }),
      noteUpdatedLog({ by: BY, note: "third", count: 3n, txHash: txHash(3), blockNumber: 3n }),
      noteUpdatedLog({ by: BY, note: "second", count: 2n, txHash: txHash(2), blockNumber: 2n }),
    ]);

    expect(records.map((r) => r.note)).toEqual(["third", "second", "first"]);
  });

  it("respects the limit (newest-first page)", () => {
    const logs = Array.from({ length: 5 }, (_, i) =>
      noteUpdatedLog({
        by: BY,
        note: `n${i + 1}`,
        count: BigInt(i + 1),
        txHash: txHash(i + 1),
        blockNumber: BigInt(i + 1),
      }),
    );

    const records = decode(logs, 2);
    expect(records.map((r) => r.note)).toEqual(["n5", "n4"]);
  });
});

